(window.STORIES=window.STORIES||[]).push(...[{"n": 82, "l": "الجزء 56 | تغيير القبله وفرض القتال", "u": "https://www.facebook.com/groups/710210019782034/permalink/788195018650200/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السادسة_والخمسون\n#تغيير_القبلة_وفرض_القتال\nكنا واقفين المرة إللي فاتت عند الحادثة إللي حصلت وعملت قلق كبير وخلت اليهود والمشركين يشمتوا في المسلمين، \nإيه إللي حصل \nفي شهر شعبان بعد سرية نخلة إللي حصلت آخر يوم رجب واتكلمنا عليها المرة إللي فاتت، نزلت الآيات بتغيير القبلة\n☆قبل ما نكمل في علماء قالوا إن تغيير القبلة كان في نصف شهر رجب، يعني حتى قبل سرية نخلة\nنرجع لموضوعنا \nاحنا كنا عارفين إن رسول الله ﷺ طول فترة مكة كان بيصلي ناحية بيت المقدس أو المسجد الأقصى، \nواستمر بعد الهجرة يصلي ناحيته لمدة سنة وسبعة أشهر في المدينة،\nوكان رسول الله ﷺ طول فترة مكة بيجعل الكعبة بينه وبين بيت المقدس بحيث إنه يصلي في اتجاه الإثنين،\nلكن لما هاجر للمدينة المكان مختلف فكان لازم يتجه ناحية بيت المقدس وكانت الكعبة في ظهر النبي ﷺ، \nفكان رسول الله ﷺ يتمنى إن ربنا يُغير له القبلة ويجعلها ناحية الكعبة،\nهو مكنش بيدعي لكن كانت مجرد رغبة، كان كل شوية ينظر للسماء منتظر جبريل ييجي يقول له إن خلاص غير القبلة،\nوده إللي حصل فعلا\nجاء جبريل عليه السلام بكلام الله:\n\"قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ ۖ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا ۚ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ ۚ\"\nوكان ده أول نَسْخ يحصل في الإسلام،\nوالنسخ معناه ببساطة إن ربنا يأمر بأمر وبعدين يغيريه لأمر تاني، فالأمر الجديد بينسخ أو بيمسح الأمر القديم،\nزي موضوع تغيير القبلة كده\nومش معنى إن ربنا استجاب لرغبة رسول الله ﷺ إن مفيش حكمة من الموضوع، ربنا لا يفعل شيء إلا لحكمة سواء احنا عرفناها وفهمناها أو لأ\n\"ذَٰلِكُمْ حُكْمُ اللَّهِ ۖ يَحْكُمُ بَيْنَكُمْ ۚ وَاللَّهُ عَلِيمٌ حَكِيمٌ \"\n☆ممكن حد يقول طيب ليه ربنا غيّر القبلة ولسه الدولة الإسلامية في بداية نشأتها يعني كان يستنى شوية وخصوصا إن اليهود كانوا مستنيين أي حاجة تحصل عشان يطعنوا في الإسلام\nالفترة إللي حصل فيها تغيير القبلة كانت أنسب وقت، عشان كل واحد يبان على حقيقته،\nعشان يبان الصادق في إيمانه وإللي هيقدر يبني دولة الإسلام ويقف قصاد الفتن والشبهات مع رسول الله ﷺ،\n من الناس إللي لسه الإيمان مش مستقر في قلوبها وممكن تسيب الإسلام بسبب شبهة ولا اثنين يقولها أعداء الإسلام\n\" وَمَا جَعَلْنَا الْقِبْلَةَ الَّتِي كُنتَ عَلَيْهَا إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ الرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ ۚ \"\nنزلت الآية وحصل بسببها فتنة كبيرة، تعالوا نشوف ردود أفعال الناس على تغيير القبلة\nاليهود إللي في المدينة كانوا من الأول فرحانين إن رسول الله ﷺ بيصلي ناحية بيت المقدس لأنها قبلتهم،\nفكانوا مفكرين إن رسول الله ﷺ هيتبعهم في دينهم بعد فترة،\nفلما اتحولت القبلة جالهم زي إحباط كده و بدأوا يشككوا المسلمين في دينهم، \nوقعدوا يقولوا محمد خالف قبلة الأنبياء قبله، ولو كان نبي كان استمر يصلي ناحية قبلة الأنبياء\n\"سَيَقُولُ السُّفَهَاءُ مِنَ النَّاسِ مَا وَلَّاهُمْ عَن قِبْلَتِهِمُ الَّتِي كَانُوا عَلَيْهَا ۚ \"\nوكلام اليهود أثّر على ضعاف الإيمان إللي عندهم شك والإسلام مش مستقر في قلوبهم وبدأوا يسألوا :\nطب ومصير الناس إللي ماتت قبل تغيير القبلة إيه، وهل ربنا هيقبل صلاتهم ولا لأ،\nوهل هياخدوا أجر على صلاتهم إللي فاتت دي ولا لأ،\n طيب ماهو لو كانت القبلة الأولى حق يبق هو ترك الحق للباطل،\nولو كان القبلة الجديدة هي إللي حق يبقى هو كان على باطل\nوكأن يعني الصلاة لبيت المقدس كانت اجتهاد من رسول الله ﷺ مش وحي من عند ربنا فمش هياخدوا أجر على صلاتهم \nومع ذلك ربنا رد عليهم عشان يطمئن المؤمنين\n\"وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ\"\nوشوفوا الفرق بينهم وبين المسلمين الصادقين الثابتين على الإيمان\nالمسلمين أول ما رسول الله ﷺ قال لهم القبلة اتغيرت وصلى بهم العصر محدش اتكلم كله صلى خلف رسول الله ﷺ وخلاص وانتهى الموضوع،\nلا وشوفوا الأعجب\nواحد من الصحابة صلى مع رسول الله ﷺ، وبعدين وصل لمسجد قباء لقى المسلمين بيصلوا وكانوا راكعين قال لهم:\nأشهد إني صليت مع رسول الله ﷺ ناحية الكعبة\nراح الصحابة وهم راكعين مدوّرين نفسهم وهم في الصلاة واتجهوا ناحية القبلة الجديدة\nوأنا عايزاكم تتخيلوا ناس راكعة بتصلي غيروا اتجاههم مائة وثمانين درجة، لأن القبلة زي ما قلنا إللي يقف وهو متجه ناحية المسجد الأقصى يبقى الكعبة في ظهره، فهم غيروا اتجاههم تماما،\nوده طبعا خلاهم يتحركوا كثير في الصلاة، ومحدش فيهم فكر إنه يستنى يتأكد من الكلام ويعرف القصة بالكامل،\nولا حد قال طيب خلاص أكمل الصلاة دي وخلاص، ومن الصلاة الجاية أصلي للقبلة الجديدة،\nكلهم بلا استثناء رجال ونساء تحولوا في نفس اللحظة،\nطاعة مُطلقة لرسول الله ﷺ\nوربنا قال إن ده اختبار كبير مش هينجح فيه غير المؤمنين،\n\"وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى الَّذِينَ هَدَى اللَّهُ \"\n¤في نقطة هنا وهي إن الحركة الكثيرة في الصلاة تبطل الصلاة، لكن الحكم ده مكنش لسه نزل على المسلمين فعشان كده اتحركوا عادي\n☆وبالمناسبة صحيح \nالمسجد إللي صلى فيه رسول الله ﷺ  مع المسلمين اتسمى بمسجد القبلتين لأن رسول الله ﷺ صلى فيه ناحية بيت المقدس وبعدين نزلت الآية بتحويل القبلة وصلى ناحية الكعبة في نفس المسجد،\nوالمسجد يا جماعة ملوش أي فضل نهائي \nعشان بس الناس إللي بتروح العمرة أو الحج يبقوا عارفين وميقعوش في البدع، هو مسجد زي أي مسجد\nأما المشركين في مكة قالوا :\nمحمد رجع لقبلتنا، وزي ما رجع لقبلتنا هيرجع لديننا قريب،\nوهو مرجعش للقبلة بتاعتنا إلا لأنه عرف إنها الحق\nربنا بقى رد على كل الناس دي بإجابة بسيطة جدا\n\"قُل لِّلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ ۚ يَهْدِي مَن يَشَاءُ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ\"\nفسواء المشرق ولا المغرب كله ملك لله، ثم العبرة مش إن الناس تتجه ناحية المشرق ولا المغرب ، \nالعبرة في تنفيذ أوامر ربنا، واتباع رسول الله ﷺ وهل فعلا لما ييجي الأمر للناس هيسمعوا الكلام بدون نقاش زي ما المؤمنين الصادقين عملوا،\nولا هيقعدوا يشككوا ويجادلوا ويشمتوا \n\"لَّيْسَ الْبِرَّ أَن تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ وَلَٰكِنَّ الْبِرَّ مَنْ آمَنَ بِالله\"\n لسه يادوب طالعين من اختبار تحويل القبلة إلا وفي اختبار تاني\nربنا فرض على المسلمين الصيام، فرض صيام شهر رمضان كامل، يعني كمان أسبوعين المسلمين هيصوموا لأول مرة في حياتهم شهر كامل،\nمفيش تدريب قبلها مفيش تهيئة، فجأة كده ربنا قال لهم إن رمضان القادم هتصوموه،\nوده صعب عليهم في بيئة صحراوية حارة زي المدينة،\n\" يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ\"\nومش بس كده ده اتفرض عليهم الزكاة بالنصاب المعروف دلوقتي،\nيعني قبل كده كان في زكاة ، لكن كان على حسب مقدرة كل \nواحد، لكن دلوقتي بقى في حد معين مطلوب منهم،\nوالإنسان بطبيعته مش بيحب القيود وخصوصا القيود المادية، والزكاة مهما كان قيمتها بسيطة إلا إن الإنسان مطبوع على حب المال :\n\"وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا\"\nومن الفرائض إللي ربنا فرضها على المسلمين في شهر شعبان كان القتال،\n☆شوفوا اختبارات وفرائض ورا بعض ورا بعض، وده كله عشان ربنا يُهيء المسلمين للي هيحصل في المستقبل\nاحنا قلنا قبل كده إن ربنا أَذِن للمسلمين بالقتال عشان يدافعوا عن نفسهم ويردوا عن أنفسهم الظلم الواقع عليهم من قريش،\nلكن دلوقتي الوضع اختلف، ربنا فرض القتال على المؤمنين\nشوفوا الآيات:\n\"وَقَاتِلُوا فِي سَبِيلِ اللَّهِ الَّذِينَ يُقَاتِلُونَكُمْ وَلا تَعْتَدُوا إِنَّ اللَّهَ لا يُحِبُّ الْمُعْتَدِينَ\"\n\"وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ ۚ وَالْفِتْنَةُ أَشَدُّ مِنَ الْقَتْلِ ۚ\"\n\"وَقَاتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ لِلَّهِ\"\nالآيات دي لما نزلت كان لها الأثر الكبير على المشركين وعلى اليهود وعلى المسلمين أنفسهم\nالناس بصفة عامة بتكره القتال لأن الحروب لا تأتي إلا بالدمار والخراب وقتل الناس\n\"كُتِبَ عَلَيْكُمُ الْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ \"\nلكن في نفس الوقت الشيء إللي المسلمين كارهينه ده قد يكون خير لهم وهم مش شايفينه،\n\"وَعَسَىٰ أَن تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَّكُمْ\"\"\nعشان كده مش معنى إن الإنسان كره شيء من أوامر ربنا إنه ميعملهاش\nيعني مينفعش واحدة تقول أنا مش عايزة أصلي أو ألبس الحجاب الشرعي عشان هي كارهة الصلاة أو الحجاب \nأوامر ربنا تتنفذ وخلاص، مش مطلوب منك تحبيها أصلا،\nالمطلوب منك تحبي ربنا، لو حبيتي ربنا هتحبي أوامره تلقائي\n☆ممكن حد يسأل وهو في خير في القتال والحروب\nالأمة إللي تجاهد بتكون عزيزة وتحترمها الأمم إللي حواليها وتعمل لها حساب،\nوكمان تقدر تسترجع أي حق أُخذ منها، \nبعكس الأمة التي لا تجاهد، تلاقي ربنا مسلط عليها الذل والأمم كلها بتحتقرها ومش عاملة لها أي حساب،\nوحقوقها ضايعة وملهاش أي حُرمة، الناس كلها بتعتدي عليها،\nوأظن إنتم شايفين واقعنا عامل إزاي\nعموم المسلمين تقبلوا أمر ربنا عادي، لكن في بعض المسلمين مشفتش الخير إللي وارء الأمر ده،\nوطلبوا من رسول الله ﷺ إنه يؤجل لهم القتال، يعني هم مقتنعين بأمر ربنا، \nبس بسبب ضعف إيمانهم وخوفهم من اتحاد المشركين واليهود، والمؤمنين لسه قلة، فقالوا نؤجل موضوع القتال، \nوالكلام ده طالع من مين، طالع من صحابة،\nلكن من حكمة ربنا إن يحصل موقف زي ده مع رسول الله ﷺ عشان احنا نعرف نتعامل معاه إزاي\nوالغريب إن الطائفة دي هي هي إللي لما كانوا في مكة مكنوش قادرين يصبروا على أذى المشركين وكانوا عايزين يحاربوهم في الوقت إللي ربنا كان مانع الرد على المشركين،\nيعني عندهم الموضوع معكوس،\nشوفوا ربنا بيقول إيه في وصف الموقف ده:\n\"أَلَمْ تَرَ إِلَى الَّذِينَ قِيلَ لَهُمْ كُفُّوا أَيْدِيَكُمْ وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ \"\nفي فترة مكة يعني، \n\"فَلَمَّا كُتِبَ عَلَيْهِمُ الْقِتَالُ إِذَا فَرِيقٌ مِّنْهُمْ يَخْشَوْنَ النَّاسَ كَخَشْيَةِ اللَّهِ أَوْ أَشَدَّ خَشْيَةً ۚ\"\nفلما ربنا فرض القتال في المدينة كان رد فعلهم مختلف،\nمع إنهم المفروض أول ناس تكون مرَحبة بالقتال لأنهم هم إللي طلبوا في الأول،\n\"وَقَالُوا رَبَّنَا لِمَ كَتَبْتَ عَلَيْنَا الْقِتَالَ لَوْلَا أَخَّرْتَنَا إِلَىٰ أَجَلٍ قَرِيبٍ\"\nلكن بسبب ضعف الإيمان دخل الخوف في قلوبهم،\nوربنا قال لهم ولأي أحد ممكن يكون في موقفهم الحل :\n\"قُلْ مَتَاعُ الدُّنْيَا قَلِيلٌ وَالْآخِرَةُ خَيْرٌ لِّمَنِ اتَّقَىٰ وَلَا تُظْلَمُونَ فَتِيلًا\"\nالدنيا مهما عيشتم فيها خايفين على عمركم فالمتاع بتاعها قليل،\nأما الآخرة هتعيشوا فيها للأبد متاعها لا ينتهي،\nووضع ربنا لهم ولنا قاعدة مهمة جدا في الآية إللي بعدها على طول\n\"أَيْنَمَا تَكُونُوا يُدْرِككُّمُ الْمَوْتُ وَلَوْ كُنتُمْ فِي بُرُوجٍ مُّشَيَّدَةٍ\"\nإنتم خايفين من اتحاد المشركين واليهود عشان ممكن يقتلوكم، طيب مانتم كده كده هتموتوا،\nمهما اختبأتم ومهما تحصّنتم في الحصون لكم عُمْر محدد مجرد ما ينتهي هتموتوا،\nسواء كنتم داخل المدينة وسط أهلكم أو بتقاتلوا المشركين واليهود، ومادام إنتم كده كده هتموتوا يبقى تموتوا وتكونوا في مكانة عالية\nفلما ذكر لهم رسول الله ﷺ آيات القرآن رجعوا عن كلامهم ومحدش تخلف منهم عن رسول الله ﷺ بعد كده\n☆وده الفرق بين المؤمن الصادق والمنافق، المؤمن الصادق إيمانه لو قل أول ما احد يذكره بالله وبالجزاء في الآخرة يرجع تاني لأوامر الله،\nلكن المنافق ولا هو هنا، عايش حياته ولا فارق معاه ربنا أساسا\nكل الأحداث دي كانت بتدل إن في حاجة هتحصل قريب\nدخل شهر رمضان وصامه المسلمون،\n احنا قلنا من شوية إن ربنا فرض صيام رمضان، لكن الفرض هنا كان فرض اختياري،\n يعني إللي عايز يصوم يصوم، وإللي مش عايز يصوم ميصمش لكن بشرط\nوهو إنه بكل يوم هيفطره هيطعم قصاده مسكين، \n\"أَيَّامًا مَّعْدُودَاتٍ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ ۚ \nوَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ ۖ فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُ ۚ وَأَن تَصُومُوا خَيْرٌ لَّكُمْ\"\nشوفوا \nفي حاجة اسمها الأمر على الوجوب والأمر على الاستحباب، يعني في أوامر من ربنا فرض مفيهاش كلام، وفي أوامر من ربنا مستحبة،\nفربنا فرض صيام رمضان وأمر به في الأول على وجه الاستحباب،\nفلما الناس جربوه واتعودوا عليه وبدأوا يختاروا الصيام بإرادتهم، ربنا فرض عليهم الصيام الفرض الإلزامي،\nطبعا باستثناء المريض أو المسافر\nفهو كان بيعمل لهم تهيئة الأول،\nزي ماحنا بنعود الأطفال الصغيرين على الصيام، فالصحابة في الوقت ده كان كل التشريعات بالنسبة لهم جديدة زي الأطفال الصغيرين،\nفكان ربنا بيمهد لهم ويعلمهم شوية شوية\nكان الصيام من الفجر إلى المغرب لكن لو الصائم لم يفطر عند المغرب ونام، لا يجوز له إنه يأكل أي شيء،\nوينتظر لتاني يوم المغرب عشان يأكل أو يشرب، وكان اقتراب الرجل من زوجته في الليل محرم طول شهر رمضان،\nفكان واحد من الأنصار بيشتغل في النخيل بالنهار وكان صائم،\n فلما حضر وقت الإفطار سأل زوجته عندك طعام؟\nقالت له : لأ، ولكني هروح أجيب لك أكل\nوكان شغال طول اليوم وتعبان فغلبته عينه ونام، فجاءته زوجته ومعاها الأكل فلما شافته نام قالت:\nخيبةً لك!! يعني بالعامية يا خيبتك\nزعلانة عليه يعني إنه نام وكان تعبان ومش هياكل غير تاني يوم المغرب،\nفلما وصل لنصف النهار وهو صائم أُغْميَ عليه، فأخبروا رسول الله ﷺ، فنزلت آية التخفيف من ربنا،\n\"أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَىٰ نِسَائِكُمْ\"\n\"وَكُلُوا وَاشْرَبُوا حَتَّىٰ يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ ۖ ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ ۚ \"\nفي شهر رمضان عرف رسول الله ﷺ إن في قافلة لقريش جاية من الشام،\nوكانت القافلة دي من أكثر قوافل قريش مالا، فيها ألف بَعير،وما لا يقل عن خمسين ألف دينار ذهبي،\n يعني لو المسلمون عرفوا يأخذوها هتبقى غنيمة كبيرة جدا لهم، وضربة اقتصادية شديدة لقريش\nوكان القائد على القافلة دي أبو سفيان بن حرب، سيد من سادات مكة، وكان إللي بيحرس القافلة حوالي ثلاثين إلى أربعين رجل،\nفلأهمية القافلة دي قرر رسول الله ﷺ إنه يخرج للقافلة دي بنفسه وجمع معاه أكبر عدد ممكن من الصحابة،\nولأول مرة يخرج الأنصار مع رسول الله ﷺ في غزوة،\n لما كان في المدينة عرض أمر الخروج للقافلة على المسلمين،\nفوافق أبو بكر ووافق عمر،\n وقال سعد بن عبادة زعيم الخزرج والله يارسول الله لو أمرتنا إننا نروح معاك لحد اليمن هنروح\nفخرج مع رسول الله ﷺ المرة دي حوالي ثلاثمائة وثلاثة عشر أو أربعة عشر أو سبعة عشر صحابي،\nكان المهاجرين ثلاثة وثمانون، وكان الأنصار مائتين وواحد وثلاثين،\nيعني ثُلثين الجيش تقريبا كان من الأنصار،\nبدأ رسول الله ﷺ يجهز ويرتب الجيش عشان يطلع يعترض قافلة أبو سفيان،\nهل هيقدر رسول الله ﷺ إنه يأخذ القافلة ويعوض المهاجرين عن خسارتهم؟\nده إللي هنعرفه الجزء الجاي إن شاء الله \n☆"}, {"n": 83, "l": "الجزء 57 | الطريق إلى بدر", "u": "https://www.facebook.com/groups/710210019782034/permalink/791373974998971/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السابعة_والخمسون\n#الطريق_إلى_بدر\nكنا واقفين المرة إللي فاتت عند رسول الله ﷺ لما بدأ يجهز الجيش عشان يخرجوا لاعتراض قافلة قريش،\nاجتمع لرسول الله ﷺ المرة دي عدد كبير من الصحابة، فقسمهم رسول الله ﷺ لمهاجرين وأنصار وجعل لكل فريق راية،\nجعل للمهاجرين راية وكانت مع علي بن أبي طالب، وجعل للأنصار راية وكانت مع سعد بن معاذ،\nوجعل راية عامة لكل الجيش وكانت مع مصعب بن عمير،\nوجعل رسول الله ﷺ واحد من الصحابة وهو قيس بن صعصعة ومعاه مجموعة صغيرة في مؤخرة الجيش عشان يحمي ظهرهم أو شيء سقط من الجيش يأخذه\nخرج رسول الله ﷺ من المدينة مع الجيش وانطلقوا ناحية بدر، لأن عيون المسلمين أو خلونا نقول بلغة عصرنا المخابرات الإسلامية عرفت إن القافلة هتمر في منطقة بدر،\nوهي على بُعد سبعين كيلو من المدينة،\nفاتجه رسول الله ﷺ ناحية بدر عشان يقطع الطريق على القافلة،\nلكن زي ما المسلمين لهم مخابرات، المشركين كمان كان لهم مخابرات \nوخصوصا إن قائد القافلة مش حد سهل ده أبو سفيان بن حرب من أذكى وأدهى العرب\nفعرف إن رسول الله ﷺ خرج من المدينة عشان يعترض القافلة، لكنه ميعرفش رسول الله ﷺ وصل لحد فين بالضبط،\nفمحبش يغامر ويضيع وقت،\n راح باعت واحد من إللي كانوا معاه لقريش عشان يقول لهم يلحقوا القافلة بتاعتهم،\nالقافلة دي فيها أموال كثيرة جدا ولو خسروها هتبقى كارثة لأن كل قريش مشاركة في القافلة دي\nبعث أبو سفيان واحد اسمه ضَمْضَم بن عمرو الغفاري، لما وصل ضمضم لمكة وقبل ما يدخل عمل حاجة عجيبة جدا\n قطع قميصه ودخل مكة يصرخ:\nيا معشر قريش!! الغَوْث الغوث!! اللطيمة اللطيمة\nالحقوا محمد هياخد أموالكم إللي مع أبو سفيان\nيعني الحقوا القافلة وأغيثوها لأن محمد خرج وهياخدها ويا تلحقوها يا متلحقوهاش\nأهل مكة شافوا منظر ضمضم وصريخه، ولسه إللي حصل في سرية نخلة مأثر فيهم، \nفكلهم قاموا وأخذوا الموضوع بجدية، وقعد أبو جهل يحمسهم وبدأوا يجهزوا جيش عشان يروحوا يلحقوا القافلة،\nوده كان من ذكاء ضمضم،\n تخيلوا لو كان دخل عليهم عادي كده وقال لهم أبو سفيان بيقول لكم الحقوه عشان محمد هيهجم على القافلة، كان رد فعلهم هيكون إيه\nكانوا هيقعدوا يسألوا في التفاصيل ، \nوليه وإزاي وإيه إللي حصل ، وعلى ما يعرفوا التفاصيل وياخدوا القرار هتكون القافلة ضاعت، \nفهو عمل الحيلة دي عشان يخرجوا بأسرع وقت ممكن\n☆وفي هنا قصة مشهورة ولكنها ضعيفة\n وهي قصة رؤيا عاتكة، وهي إن عاتكة عمة رسول الله ﷺ شافت رؤيا قبل ما ضمضم ييجي بثلاثة أيام وكان تفسيرها إن ضمضم هييجي وهيحصل قلق في مكة، والناس قعدوا يسخروا منها، وهي قصة طويلة يعني،\nبس هي ضعيفة لا تصح، فمش هقولها اختصارا للوقت،\nوهي من القصص التي شاعت ولم تثبت في السيرة النبوية \nقريش جمعت جيش كبير جدا حوالي ألف وثلاثمائة مقاتل وخرجوا عشان ينقذوا القافلة،\nوخرج كل سادات قريش تقريبا، أبو جهل ، عقبة بن أبي مُعَيْط، ، عتبة بن ربيعة، أُبي بن خلف، وغيرهم،\nولم يخرج أبو لهب ...خاف، وخلى واحد تاني كان عليه دين لأبي لهب يخرج مكانه،\n فقال له أبو لهب اخرج مكاني وأنا هتنازل عن الدين، فخرج الرجل مكان أبي لهب،\nأمية بن خلف بقى مكنش عايز يطلع معاهم\nلأنه خايف من كلام سعد بن معاذ إللي كان قاله له قبل كده إن رسول الله ﷺ قال إنهم هيقتلوه،\nفلما عرف أبو جهل إن أمية بن خلف مش ناوي يخرج جاء له وقال له:\nيا أبا صفوان!\nإنت لو قعدت ومطلعتش مع الناس، الناس هيتكاسلوا ومش هيرضوا يخرجوا، فأقنعه بالخروج معاهم،\nولما تجهز أمية بن خلف للخروج زوجته قالت له :\nمش فاكر لما صاحبك من يثرب قال لك إن محمد قال إنه هيقتلك، بلاش تخرج\nفقال لها: أنا مش هخرج معاهم، أنا بس همشي معاهم شوية وأرجع\nخرجوا كلهم واختار المشركون أبو جهل عشان يكون قائد الجيش، \nلكن واجهتهم مشكلة\nوهي إنهم خافوا من قبيلة بني بكر، خافوا ليخرجوا من مكة فتقوم بني بكر هاجمة على مكة وهم كان بينهم ثارات قديمة، فاحتاروا\nفجاء الشيطان وتمثل في صورة رجل من أشراف بني كنانة هو سراقة بن مالك وقال لهم:\nأنا هجيركم وأحميكم من بني بكر فاخرجوا ومتقلقوش \n\"وَإِذْ زَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ الْيَوْمَ مِنَ النَّاسِ وَإِنِّي جَارٌ لَّكُمْ\"\nفانطلق الجيش من مكة متوجه ناحية المدينة، وكان جيشهم فيه مائة فرس وستمائة درع، ومعاهم جمال كثيرة جدا ،\nوكانوا بيذبحوا كل يوم عشرة جمال عشان ياكلوها،\nفي حين إن المسلمين الثلاثمائة إللي خرجوا كان كل ثلاثة بيبدلوا على بعير،\nيعني واحد يركب واثنين يمشوا وهكذا، وكان أكلهم في الرحلة دي التمر، فالمسلمين بصفة عامة كانوا فقراء،\nفلو بصينا للوضع هنلافي إن رسول الله ﷺ في خطر،\nناس جايين متجهزين وواكلين وعلى أتم الاستعداد،\n في مقابل رسول الله ﷺ وأصحابه إللي خارجين عشان يعترضوا قافلة عليها أربعين رجل فقط\nفي الوقت إللي جيش قريش كان خرج من مكة،\n كان أبو سفيان عرف إن جيش رسول الله ﷺ هينتظر القافلة في بدر،\nفراح أبو سفيان مغير اتجاهه وعرف يهرب بالقافلة من طريق تاني\nكده القافلة بقت في أمان، فبعث أبو سفيان رسالة للجيش إللي خرج يقول لهم ارجعوا لأن خلاص السبب إللي خرجتم عشانه بقى في أمان فمفيش داعي لأي قتال،\nطبعا إللي فرح بالموضوع ده أكثر واحد أمية بن خلف \nوفي ناس برده مكنوش عايزين يدخلوا في معركة مع رسول الله ﷺ،  لأنهم هيقاتلوا أبناءهم أو إخوانهم،\nفمصدقوا إن القافلة بقت في أمان عشان يرجعوا، لكن أبو جهل معجبوش الموضوع، \nراح قايم واقف وقال لهم:\nوالله ما هنرجع إلا لما نوصل بدر ونقعد فيها ثلاثة أيام فنذبح الذبائح ونشرب الخمر ونعمل حفلة وتسمع بينا العرب وبقوتنا فيخافوا مننا \n\"خَرَجُوا مِنْ دِيَارِهِمْ بَطَرًا وَرِئَاءَ النَّاسِ وَيَصُدُّونَ عَنْ سَبِيلِ اللَّهِ \"\nلكن في ناس رفضت كلام أبو جهل، وانشقوا عنه زي الأَخنس بن شُرَيْق، أخذ معاه بني زُهْرة وكانوا ثلاثمائة رجل ورجع بهم لمكة، وبكده جيش الكفار بقى ألف رجل فقط،\nلكن برده لسه العدد كبير في مقابل ثلاثمائة من المسلمين\nوصل جيش مكة لمكان قريب من بدر اسمه العُدْوَة القصوى،\nفي الأثناء دي كان وصل لرسول الله ﷺ الأخبار إن القافلة هربت وإن قريش خرجوا بجيش كامل عشان يحاربوا المسلمين\nطبعا الوضع صعب دلوقتي، احنا خارجين من المدينة بجيش قوي بالنسبة لقافلة بسيطة،\nلكن بالنسة لجيش منظم موقفنا خطير، واحنا مش عاملين حسابنا، طيب إيه الحل\nمفيش غير حلين : إما إن رسول الله ﷺ يرجع للمدينة ويتجنب مواجهة المشركين، \nأو إنه يتقدم لبدر ويحصل الصدام والمواجهة مع قريش،\nوالاختيارين أحلاهما مر\nتعالوا كده نفكر مع رسول الله ﷺ في مميزات وعيوب كل اختيار\n◇الاختيار الأول: إنهم ينسحبوا ويرجعوا للمدينة،\nلو المسلمين انسحبوا ده هيهز كيان المسلمين ويضعفهم،\nوهيخلي المشركين يتمادوا في حرب المسلمين، كل شوية هنلاقيهم جايين بجيش،\nوكمان هيضيع مكاسب سرية نخلة بإنهم بقى لهم شوكة والناس بتخاف منهم،\nثم مش بعيد إن المسلمين لو انسحبوا ورجعوا للمدينة المشركين يروحوا وراهم ويغزوا المدينة ودي كارثة \n◇الاختيار الثاني: إنهم يواجهوا المشركين ويقاتلوهم\nلكن المشكلة إن أعدادهم قليلة وغير مجهزين\nرسول الله ﷺ كان رأيه إنه يواجه المشركين و يقاتلهم،\nلكنه ميقدرش يفرض رأيه على الناس إللي معاه زي أبو جهل ما عمل،\nلأن احنا في الإسلام عندنا مبدأ الشورى، يعني مش عشان أنا شايفة إن قراري صح أقوم أنفذه ومش مهم الناس إللي معايا رأيهم إيه\nلازم استشيرهم وأخذ رأيهم لأن الموصوع ميخصنيش أنا لوحدي\nوهو ده إللي عمله رسول الله ﷺ، جمع الجيش بتاعه سواء القادة أو عامة الجيش وبدأ يسألهم نعمل إيه؟\nالمستشار الأول لرسول الله ﷺ أبو بكر الصديق  قال له :\nنقاتلهم يارسول الله\nالمستشار الثاني عمر بن الخطاب رضي الله عنه قال نفس كلام أبو بكر،\nواحد من أصحابه ﷺ وهو المقداد بن عمرو قال لرسول الله كلمة فرح بها رسول الله ﷺ جدا قال:\nيا رسول الله! اعمل إللي إنت شايفه صح، فوالله مش هنقول لك كما قال بنو إسرائيل لموسى اذهب أنت وربك فقاتلا فإنا هاهنا قاعدون،\nولكن هنقول لك : اذهب أنت وربك فقاتلا إنا معكما مقاتلون\n☆طبعا إنتم أكيد فاكرين بني إسرائيل لما رفضوا يدخلوا الأرض المقدسة وبعدين قالوا لموسى روح انت وربك فقاتلا واحنا هنستناكم هنا ، وبعدين ربنا عاقبهم بالتّيه\nأهه الصحابة ترجموا قصة نبي من الأنبياء لواقع عملي،\nسورة البقرة كانت أول سورة نزلت في المدينة بعد الهجرة، وكانت بتتكلم عن بني إسرائيل بعد ما موسى عليه السلام خرج بهم من مصر،\nفربنا بيقول للصحابة شوفوا بني إسرائيل عملوا إيه مع نبيهم، بعد ما ربنا نجاهم من فرعون الطاغية،\nخدوا بالكم متعملوش زيهم\nالصحابة فهموا من قصص الأنبياء إن ربنا مش بيحكي لهم القصص دي للتسلية، ولكن للعبرة والعظة والتعلّم\nوجاء وقت التطبيق العملي\nربنا نجّى الصحابة من ظلم قريش وخرجوا مع رسول الله ﷺ  لمكان آمن،\nفجاء وقت الاختبار دلوقتي يا ترى هتعملوا إيه، هتعملوا زي بني إسرائيل ولا هيكون لكم موقف ثاني\nوكان للصحابة فعلا موقف ثاني، الصحابة مكرروش غلطة بني إسرائيل واتعلموا الدرس،\nوقالوا لرسول الله ﷺ إنهم معاه ومش هيسبوه مهما كان قراره\n¤السؤال بقى، ياترى هل احنا اتعلمنا الدرس من قصص الأنبياء  زي الصحابة كده، ولا بنكرر أخطاء بني إسرائيل وغيرها من الأمم السابقة\nعلى الرغم من كلام المقداد إلا إن رسول الله ﷺ لسه بيطلب من أصحابه المشورة:\nأشيروا علي أيها الناس! نعمل إيه؟!\nطبعا احنا مستغربين من تكرار طلب رسول الله ﷺ المشورة بعد كلام أبو بكر وعمر والمقداد\nأصل إللي اتكلموا دول كانوا من المهاجرين ورسول الله ﷺ عايز يسمع رأي الأنصار،\nلأن بيعة العقبة الثانية إللي بايع فيها الأنصار كانت بيعة على نُصرة رسول الله ﷺ والدفاع عنه داخل المدينة،\nوهم دلوقتي خارج المدينة فرسول الله ﷺ عايز يعرف رأي الأنصار إيه وخصوصا إنهم ثلثين الجيش يعني هم الأغلبية\nفلما كرر رسول الله ﷺ طلب المشورة ، سعد بن معاذ سيد الأوس وحامل لواء الأنصار انتبه وقال لرسول الله ﷺ:\nكأنك عايز رأينا احنا يا رسول الله\nفقال له رسول الله ﷺ: أيوة عايز رأيكم!\nفقال سعد بن معاذ رضي الله عنه:\nيا رسول الله! احنا آمنا بك وصدقناك، وشهدنا إن إللي إنت جئت به ده هو الحق\nوعلى الأساس ده عاهدناك على السمع والطاعة، فاعمل إللي إنت عايزه يا رسول الله وشايفه مناسب،\n فوالله لو مشيت في البحر لنمشي وراك من غير ما ولا واحد فينا يتخلف عنك\nواحنا لا نكره إنك تستعملنا في مواجهة عدونا، \nفاحنا بنصبر في الحرب، ولعل ربنا يُريك منا إللي يفرحك ويُقر عينك به، فامشي على بركة الله\nلعلك كنت خايف يا رسول الله إن الأنصار شايفين إن حقك عليهم إنهم ينصروك داخل المدينة فقط\nلكن أنا بقول لك بالنيابة عن الأنصار \nروح المكان إللي إنت عايزه، واعمل علاقات مع الناس إللي إنت عايزها، \nواقطع علاقات مع الناس إللي إنت مش عايزها،\nوخذ من أموالنا إللي إنت عايزه، وأعطنا إللي إنت عايزه،\nمع العلم إن إللي إنت بتأخذه مننا أحب إلينا من إللي إنت بتتركه لنا،\nوأي قرار احنا بناخده هو تابع لقرارك\n☆الأنصار فعلا أنصار لله ولرسوله\nعارفين سعد بن معاذ ده اهتز لموته عرش الرحمن،\nفتخيلوا صدق كلماته وأفعاله مع رسول الله ﷺ\nرسول الله ﷺ بعد ما سمع كلام سعد فرح واتحرك بكل نشاط وحماس وقال لهم :\n سيروا وأبشروا، فإن الله وعدني إما النصر على المشركين أو إننا نأخذ القافلة \nبدأ المسلمين يخططوا إزاي هيواجهوا المشركين،\nعملوا إيه واختاروا أرض المعركة إزاي،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 84, "l": "الجزء 58 | قبل معركة بدر", "u": "https://www.facebook.com/groups/710210019782034/permalink/791380384998330/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثامنة_والخمسون\n#قبل_معركة_بدر\nاتكلمنا المرة إللي فاتت عن تجهيزات جيش مكة لحرب المسلمين، وشوفنا في المقابل قلة تجهيزات الجيش الإسلامي بقيادة رسول الله ﷺ،\nوصل جيش مكة لمكان اسمه العُدْوة القصوى يعني جنوب وادي بدر،\nووصل رسول الله ﷺ للعُدْوة الدنيا يعني للجزء الشمالي منه،\nوفي نفس الوقت ده كانت قافلة أبو سفيان موجودة على نفس خط الجيشين،\nيعني هم الثلاثة كانوا على ثلاث خطوط متوازية ||| ومحدش يعرف حاجة عن الثاني \nشوفوا وصف ربنا في القرآن:\n\"أَنتُم بِالْعُدْوَةِ الدُّنْيَا وَهُم بِالْعُدْوَةِ الْقُصْوَىٰ وَالرَّكْبُ أَسْفَلَ مِنكُمْ ۚوَلَوْ تَوَاعَدتُّمْ لَاخْتَلَفْتُمْ فِي الْمِيعَادِ ۙ وَلَٰكِن لِّيَقْضِيَ اللَّهُ أَمْرًا كَانَ مَفْعُولًا\"\nدلوقتي محتاجين نعرف مكان الجيش بالضبط، فخرج رسول الله ﷺ بنفسه ومعاه أبو بكر الصديق في عملية استكشافية وعرفوا مكان الجيش إللي كان في العُدوة القصوى،\nلكن رسول الله ﷺ معرفش عددهم كان كم بالضبط، ولا عدد قادتهم ولا وضع الجيش الداخلي كان إيه\nفأرسل زي ما تقولوا فرقة استكشافية صغيرة \nكان فيها علي بن أبي طالب والزبير بن العوام وسعد بن أبي وقاص،\nقدرت الفرقة دي إنها تمسك غلامين من جيش قريش، فأخذوهما وراحوا لرسول الله ﷺ،\nوبدأ يسألهم عن الجيش وعددهم أد إيه، فقالا له : احنا منعرفش\nفسألهم : طيب هم بيذبحوا في اليوم كم بعير، يعني بيذبحوا كم جمل عشان يأكلوا؟\nفقالا له: يوم بيذبحوا تسعة ويوم بيذبحوا عشرة\nفقال رسول الله ﷺ :\nعدد الجيش ما بين التسعمائة والألف\nلأنه كان من المعروف عندهم إن المائة شخص بيكفيهم جمل واحد.\nفسألهم رسول الله ﷺ:\nفيهم مين من أشراف قريش؟!\nفقالا له: عتبة بن ربيعة وشيبة بن ربيعة\n 《فاكرينهم وفاكرين إرسالهم لعدّاس لرسول الله ﷺ لما كان في الطائف؟》\nأمية بن خلف وأبو جهل بن هشام، وعقبة بن أبي مُعيط.\nفكده كل قادة المشركين موجودين في الجيش وعرف رسول الله ﷺ أعداد جيش المشركين وأنهم ثلاثة أضعاف جيش المسلمين،\nيبقى احنا محتاجين نعمل خطة عشان نعوض الفرق في العدد، احنا عددنا قليل بس عندنا إمكانيات تانية ممكن نستغلها\nومن الحاجات إللي ممكن نستغلها لمصلحتنا هي أرض المعركة\nفاتجه رسول الله ﷺ لأرض بدر عشان يقيم معسكر المسلمين فيها، \n☆وفي هنا قصة مشهورة عن واحد من الصحابة اسمه  الحُبَاب بن المنذر إن هو إللي أشار على رسول الله ﷺ إنه يجعل بئر بدر خلفه بحيث إنهم يمنعوا المشركين من إنهم يأخذوا الماء،\nلكن القصة دي غير صحيحة \nيعني رسول الله ﷺ على طول بيستشير أصحابه وشفنا أمثلة كثيرة لكده لكن في الموقف ده محصلش إن حد أشار على رسول الله ﷺ إنه يختار أرض المعركة\n،استقر رسول الله ﷺ في أرض بدر وجاء الليل، وفجأة نزل المطر\nوالمطر مع أرض رملية يعمل طيب ويخلي الحركة صعبة\nلكن ده محصلش مع المسلمين،\nربنا أنزل عليهم مطر خفيف هين، خلى الأرض متماسكة من تحت أرجلهم، وشربوا منه واغتسلوا،\nفي حين إن المطر نزل على معسكر المشركين شديد جدا وبقت الأرض مطينة عندهم وعملت برك مية خلتهم مش عارفين يتحركوا\nالواحد لما يكون وراه مشوار مهم أو امتحان مهم بيبقى مش عارف ينام مهما حاول، بيبقى قلقان وبيقعد يفكر هيعمل إيه،\nفما بالكم بقى المسلمين هيواجهوا جيش ثلاثة أضعاف عددهم، \nفالطبيعي إنهم يكونوا قلقانين وبيفكروا ومش عارفين يناموا،\nوخصوصا إن دي أول معركة حقيقية للمسلمين\nيعني هم في السرايا والغزوات إللي قبل كده كانوا بيخرجوا من المدينة عشان يعترضوا قوافل قريش، بس مكنش بيحصل مواجهة بينهم وبين القوافل إللي كانوا بيخرجوا عشانها،\nوطبعا استفادوا كثير من من السرايا والغزوات دي بإنهم كسروا الحاجز النفسي إللي كان عندهم، متخليني بقالهم أربعة عشرة عام لم يقاتلوا،\nفكانت السرايا والغزوات دي زي فترة تدريب سواء تدريب نفسي أو جسدي فهم تدربوا على ركوب الخيل وعلى التخطيط للمعارك وعلى فنون القتال،\nفكل ده كان تمهيد للمعركة الكبيرة إللي هتحصل دلوقتي\nفالمفروض إن اي أحد في موقفهم لا يذوق النوم\nلكن إللي حصل كان غير كده، الجيش كله نام\nربنا جعل المسلمين كلهم يناموا بما فيهم الحرس إللي كان بيحرس جيش المسلمين\nربنا أنزل عليهم الأمان وهدوء الأعصاب محدش بقى يفكر في عدد ولا طريقة قتال ناموا مرتاحين البال ولا كأنهم في أرض معركة\nمعسكر المشركين بقى كان مضطرب من البداية أصلا\nأمية بن خلف مكنش عايز يقاتل، والأخْنَس بن شُرَيق انسحب أصلا،\nوالناس مترددة مش عارفين هيقاتلوا ليه بعد ما القافلة خلاص بقت في أمان،\nلدرجة إن عتبة بن ربيعة وهي سيد من سادات مكة وكان رافض إنه يقاتل رسول الله ﷺ قال للناس:\nيا جماعة اسمعوا كلامي، إنتم لو دخلتم في معركة مع المسلمين هتقتلوا منهم ناس،\n والناس دي إما آباءكم أو أبنائكم، وكل واحد هيبص للثاني ويقول له إنت إللي قتلت أخي أو أبي يوم بدر فيكره بعضكم بعض ،فخلوها في رقبتي وارجعوا\nفغضب أبو جهل وقال : واضح إنك جبان\n هو محمد وأصحابه إيه غير مائة رجل هنخلص عليهم في قاعدة\nفقال له عتبة بن ربيعة: بكرة تعرف مين الجبان إللي هيودي قومه في داهية\nووجه عتبة الكلام لقومه وقال لهم : والله كأني شايفهم بيضربوكم وبيقضوا عليكم\nطبعا الكلام ده قصاد الناس كلها ، فده أثر على نفسيتهم بالسلب، يعني القادة عمالين يتخانقوا ومترددين أمّال احنا الجنود نعمل إيه\nوالموضوع موقفش على كده، جاء حكيم بن حزام إللي كان بيساعد المسلمين المحاصرين في شعب أبي طالب لو تفتكروا،\nوقال لعتبة بن ربيعة:\nتحب إنك تاخد شرف إنك حميت الناس من القتل إللي ممكن يحصل لهم النهاردة\nفقال له عتبة : أعمل إيه طيب\nفقال له حكيم:\nإنتم عايزين من محمد دم عمرو بن الحضرمي إللي قُتل في سرية نخلة صح، خلاص ادفع إنت لأهله الدية بتاعته وترجع بالناس\nفقال له : أنا معنديش مشكلة، المشكلة في أبو جهل فانت  روح له وقل له :\nإيه رأيك ترجع بالناس إللي معاك دي عن ابن عمك؟ \n☆والمقصود هنا مش إن أبو جهل يبقى ابن عم رسول الله ﷺ هو يقصد إنه بيلتقي مع رسول الله ﷺ في نسبه مع جد من أجداده\nفراح حكيم بن حزام لأبي جهل وكلمه، فرد عليه أبو جهل وقال له: وهو عتبة ملقاش حد غيرك يبعته\nفقال له حكيم: أه ملقاش غيري، وإنت بتتكلم عن سيد من سادات مكة على فكرة\nفرفض أبو جهل الرجوع وصمم على القتال\nراح واحد منهم عشان يشوف عدد المسلمين أد إيه، ورجع وقال لهم إنهم حوالي ثلاثمائة، وإن المسلمين شكلهم مش سهلين خالص، ومفيش واحد فيهم هيستسلم أو يقبل الموت إلا لما يقتل رجل منكم،\nفلو مات مننا ثلاثمائة رجل يبقى إيه المكسب إللي احنا حققناه\nفكروا كويس وخدوا القرار\nالتردد والقلق وعدم الاتفاق بين قادة المشركين كان سبب كبير في اضطراب جيش المشركين، \nوالقلق والحيرة دي طبعا منعتم من النوم وخلتهم قلقانين ومش عارفين يعملوا إيه،\nناس طالعة تحارب وهي أصلا مش مقتنعة بالحرب دي، هتكون النتيجة عاملة إزاي\nعدت الليلة على الفريقين زي ما شفنا وجاء صباح يوم المعركة.\nاليوم بدأ إزاي، وإيه الأحداث إللي حصلت في معركة بدر،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 85, "l": "الجزء 59 | غزوة بدر الكبرى الجزء الأول | بداية المعركه", "u": "https://www.facebook.com/groups/710210019782034/permalink/795267724609596/", "t": "عارفين نشيد سأروي لكم عن قصة للمصطفي بعد متقرئو القصه دي اسمعو النشيد \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_التاسعة_والخمسون\n#غزوة_بدر_الكبرى_الجزء_الأول\n#بداية_المعركة\nوقفنا المرة إللي فاتت عند صباح يوم معركة بدر، استيقظ المسلمون بعد ما ربنا جعلهم يناموا، وكان أول شيء رسول الله ﷺ عمله هو الدعاء،\nأيوة احنا بناخد بالأسباب وبنعمل إللي علينا لكن من غير توفيق ربنا مش هيبقى في أي نتيجة كويسة\nوهنلاقي إن الدعاء مستمر معانا على طول، يعني رسول الله ﷺ لما خرج من المدينة قعد يدعي ربنا للصحابة ويقول:\n\"اللهم إنهم حُفاة فاحملهم، اللهم إنهم عُراة فاكسهم،\nاللهم إنهم جِياع فأشبعهم\"\nولما جاء قبل المعركة برده قعد يدعي ربنا بأنه يعطيه نصره إللي وعده به،\nفرسول الله ﷺ مبطلش دعاء خالص حتى لما يدخلوا المعركة،\nقلبه معلق بالله، يارب انصرهم يارب لو المجموعة دي هلكت مفيش حد هيعبدك، لأن الأرض في الزمن ده مكنش في حد بيعبد ربنا صح غير المسلمين\nفرسول الله ﷺ وهو رسول الله قعد يلح على ربنا في الدعاء، مع إنه أصلا دعاؤه مستجاب من غير إلحاح،\nحتى أبو بكر الصديق رضي الله عنه لما لقاه بيدعي بشدة قال له : يا رسول الله!\nخفف شوية من الدعاء متخفش ربنا مش هيخلف وعده معاك!\nومكنش بس رسول الله ﷺ إللي بيدعي، ده كل الجيش كان بيدعي وقلبه متعلق بالله، ودي أهم صفة من صفات الجيش إللي ربنا ينصره\nلما الجيش يكون قلبه متعلق بالله ومؤمن به وعنده يقين تام إن النصر من عند الله ربنا هينصره أكيد\nومش بس المسلمين هم إللي كانوا بيدعوا ،ده المشركين كمان كانوا بيدعوا ربنا تخيلوا\nبيدعوا ربنا إنه ينصرهم على المسلمين\nأبو جهل كان بيقول :\n\"يارب! محمد قطع الرحم وجالنا بدين إحنا منعرفوش، فانصر في المعركة دي الأحب والأقرب لك\" \n☆إنتم متخيلين بعد ده كله والسنين والمعجزات دي كلها في مكة وربنا قال عن المشركين إنهم عارفين إن رسول الله ﷺ صادق وهم إللي جحدوا.. أبو جهل بيدعي إن الأحب إللي الله هو إللي ينتصر\nده إنت لو بتدعي على نفسك مش هتقول كده\nفحاجة من الإثنين:\nيا إما أبو جهل بيدعي بالدعاء ده عشان يحفز الناس إللي معنوياتها صفر وكارهة القتال أصلا ويخليهم يعيشوا وَهْم إنهم على حق وبيقاتلوا في سبيل قضية عادلة،\n وإنهم بيعملوا الخير للوطن وللعالم لما يقضوا على المسلمين إللي عايزين ينشروا الفساد في الأرض،\nوإن المليار ونص عايزين يقتلوا الدنيا كلها عشان يعيشوا لوحدهم يا حرام\nأو إن أبو جهل من كثرة ما عاش دور إنه زعيم وبيقنع الناس بإن هو المُصلح وصاحب الأخلاق المدافع عن الحق صدق نفسه وإن هو عبقري زمانه\n☆شخصية أبو جهل دي موجودة في كل العصور،\nيبدأ بخداع الناس لحد ما يحقق مصلحته وبعدين يصدق نفسه وهو أصلا من المجرمين إللي بيعذبوا الناس وبينهبوا أموالهم،\nوتسمعوه يتكلم عن الشرف والأمانة ولا كأنه اتخلق عشانها\nالمهم،\nبدأ رسول الله ﷺ يجهّز جيش المسلمين إللي هيقاتل المشركين\nأول مرة العرب يتجمعوا تحت راية واحدة وتحت دين واحد،\nجعلهم رسول الله ﷺ صفوف متساوية في منتهى النظام،\nوهو بيصف الصفوف كان بيقول لهم الخطة إللي هيبدأوا بها القتال قال:\nمحدش يرمي السهام على المشركين إلا لما يقربوا منكم، عشان مترموش السهام وهمّ لسه بعيد فلا تصيبهم ،ويبقى ضيعتم الذخيرة بتاعتكم على الفاضي\nومحدش يطلع سيفه من غمده إلا لما يقترب منكم الجيش جدا\nودي ثاني صفة من صفات الجيش إللي ربنا بينصره\nالأخذ بالأسباب\nيعني إن المسلمين يستعدوا كويس جدا للمعركة باللي يملكوه، ويأخذوا بأسباب النصر ويعملوا كل إللي يقدروا عليه عشان يحققوا النصر على أعدائهم، وشوفوا ربنا بيقول إيه:\n\"وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ وَمِنْ رِبَاطِ الخَيْل\"\nيعني شوف إنت استطاعتك إيه واعمله وملكش دعوة بالباقي\nالمعركة خلاص قربت تبدأ ورسول الله ﷺ  بيرص الصفوف لقى في واحد من الصحابة طالع عن الصف، ومش واقف عدل\nفقال له رسول الله ﷺ: \nاستقم ! يعني قف في الصف مضبوط وكان في يد رسول الله ﷺ زي عود أو خشبة كده زقّه بها أو زي ما تقولوا ضربه بها،\nزي مثلا لما نكون بنعمل حاجة في البيت وفي حد وقف قصادنا فنقول له وسّع كده واحنا بنخبط على إيده أو على ظهره،\nخبطة خفيفة يعني\nفالصحابي ده وكان اسمه 《سَواد بن غَزية》من الأنصار\n قال له: يا رسول الله أوجعتني\nوإنت جئت بالحق والعدل ولازم تعطيني القصاص\n☆سواد عارف إن رسول الله ﷺ هو أكثر واحد بيطبق شرع ربنا، ماهو هو إللي قال:\n\"من ضَرَب بسوط ظلما، اقتُصَّ منه يوم القيامة\"\nوقال للصحابة : أتدرون من المُفلس؟\n قالوا: المفلس فينا من لا درهم له ولا متاع، فقال: \nإنّ المفلس من أمّتي يأتي يوم القيامة بصلاة وصيام وزكاة ويأتي قد شتم هذا، وقذف هذا،\n وأكل مال هذا، وسفك دم هذا، وضرب هذا، فيُعْطَى هذا من حسناته، وهذا من حسناته،\n فإن فنيت حسناته قبل أن يقضى ما عليه أُخِذَ من خطاياهم فطرحت عليه ثمّ طرح في النّار\"\nفسواد استغل إن رسول الله ﷺ هو اتقى الناس عشان يقتص منه،\nوالصحابة مستغربين من الكلام إللي سمعوه من سواد بن غزية بيقوله لرسول الله ﷺ وإنه إزاي بيطلب القصاص لنفسه\nيعني الموضوع بسيط وحاجة عادية مش مستاهلة القصاص وكمان ده رسول الله ﷺ قائد الدولة الإسلامية يعني الواحد يعديها عادي\nوإنت عايز تقتص منه\nرسول الله ﷺ بكل بساطة أعطاه العود عشان يقتص منه،\nمن غير ما يتكلم ولا كلمة، ولا يقول له دي كانت ضربة خفيفة، ولّا هو الواحد ميعرفش يهزر معاك ولا إنت إزاي تقول لي أنا الكلام ده \nومش بس رسول الله ﷺ أعطى له العود، ده كمان كشف عن بطنه ﷺ لأنه لما ضرب سواد بالعود كانت بطنه مكشوفة فأراد إن الضربة تكون على الجلد مباشرة زيه بالضبط،\nطبعا كل ده والصحابة شايفين الموقف وهاين عليهم ياكلوه\nفأول ما رسول الله ﷺ كشف عن بطنه وقال لسواد اقتص مني، قام سواد وحضن بطن النبي ﷺ وقبّله\nفرسول الله ﷺ استغرب من إللي عمله وسأله:\nإيه إللي خلاك تعمل كده يا سواد؟!\nفقال له سواد :\nيا رسول الله! إنت شايف الوضع إللي احنا فيه وأنا ممكن أموت فحبيت إن آخر حاجة تحصل لي إن جلدي يمس جلدك\nسواد لم يمت في بدر، ولكنه لفت نظرنا لصفة ثالثة من صفات الجيش إللي ربنا بينصره، وهي إن القائد يكون متلاحم مع شعبه وجنوده،\nلخصها رسول الله ﷺ في بيعة العقبة الثانية بكلمة :\n\"أنا منكم وأنتم مني\" \nأنا أشتغل معاكم زي مانتم بتشتغلوا، أنا أتحمل الألم زيكم بالضبط،\nاحنا قلنا إن المسلمين لما خرجوا لغزوة بدر كانوا بيبدلوا بينهم على بعير واحد،\nوكان رسول الله ﷺ بيبدل مع علي بن أبي طالب وصاحبي اسمه مرثد بن أبي مرثد،\nفقالا لرسول الله ﷺ:  يا رسول الله احنا هنمشي عنك وإنت خليك راكب على الجمل\nفقال لهما رسول الله ﷺ : أنتما مش أقوى مني، ولا أنا مستغني عن الأجر، أنا عايز أجر زيي زيكم\nفتخيلوا لما يكون القائد متداخل مع الجنود بالطريقة دي، هيحبوه أد إيه ويفدوه بأرواحهم إزاي\nوعلى فكرة كل قادة التاريخ الإسلامي صلاح الدين الأيوبي ، وقطز ، وعبد الرحمن الناصر ، وموسى بن نصير ، ويوسف بن تاشفين .. وغيرهم كثير كان فيهم صفة التلاحم مع جنودهم دي\n♡أقول لكم معلومة هتفيدكم في تربية عيالكم \nلما تطبقوا قاعدة التلاحم دي مع عيالكم في البيت وتحسسوهم إنكم حاسين بألمهم في المذاكرة، وألمهم في التعامل مع الناس،\nوألمهم في مساعدتكم في البيت،\nوحاسين برغباتهم في عمل الغلط وإن الموضوع فعلا صعب وإنكم مريتم بنفس المراحل بس قاومتم ومرة تنجحوا ومرة تفشلوا هتلاقوا منهم لين كبير جدا وهيبقى في تفاهم بينكم كبير،\nبعكس الشخصية الدكتاتورية إللي مفيش وراها غير الأمر والنهي واعملوا إللي بقول عليه من غير نقاش\nطبقوا قاعدة التلاحم دي مع الناس إللي حواليكم علاقتكم بيهم هتتغير للأحسن كتير \n◇معلومة مجربة \nنرجع لأرض المعركة ونشوف إللي حصل، قبل ما المعركة تبتدي خالص واحد من المشركين رمى سهم ناحية معسكر المسلمين فكان واحد اسمه حارثة بن سراقة بيشرب من حوض بئر بدر فأصابه السهم ومات وكان أول قتيل في غزوة بدر،\nفكده هو مات قبل ما المعركة تبتدي، فهو وضعه إيه، هل يحسب شهيد ولا لأ\nحتى أمه الرُّبيّع بنت النضر أخت أنس بن النضر وعمة أنس بن مالك إللي هيكون خادم رسول الله ﷺ بعدين سألت رسول الله ﷺ عن حال ابنها وهل هو في الجنة ولّا لأ، \nفرسول الله طمنها وقال لها إنه مش بس دخل الجنة،\nلأ ده كمان مكانه الفردوس الأعلى من الجنة\nوقف الجيشين قصاد بعض، وراح واحد من المشركين أقسم إنه هيشرب من ماء بدر إللي هو ناحية رسول الله ﷺ وانطلق الرجل ناحية البئر، فاعترضه حمزة بن عبد المطلب فقطع رجله،\nوالرجل قعد يقاوم عشان عايز يوفي بقسمه لحد ما وصل للبئر وقبل ما يشرب قتله حمزة بن عبد المطلب،\nكده دي أول نقطة في صالح المسلمين، رفعت معنوياتهم وغاظت المشركين خلت ثلاثة منهم يقوموا للمبارز\nوكان من عادة العرب إنهم قبل ما يبتدوا بالحرب كان يخرج كم واحد من كل جيش يطلب المبارزة،\nيعني رجل يخرج من الجيش ويقول للجيش المقابل اخرجوا لي واحد أبارزه رجل لرجل كنوع من الاستعراض يعني\nمين الثلاثة إللي قاموا ؟\nقام عتبة بن ربيعة وأخوه شيبة بن ربيعة وابنه الوليد بن عتبة وهم من أقوى وأشد فرسان مكة\n☆عتبة بن ربيعة إللي كان لسه من شوية عمال يقول للناس ارجعوا قام أول واحد يقاتل المسلمين \nعلى الرغم من إن عتبة بن ربيعة كان صاحب أراء حكيمة،\nوكان من الحكماء القلائل في قريش،\nوشوفنا إزاي إنه لآخر لحظة عمال يقنع الجيش بإنه يرجع عن قتال المسلمين،\nحتى رسول الله ﷺ لما شافه من بعيد قبل بدء المعركة وكان راكب على جمل أحمر قال عنه:\n \"إن يَكن في أحد من القوم خير فعند صاحب الجمل الأحمر، إن يُطيعوه يَرشُدوا\"\nإلا إنه عنده مرض خطير مضيع معظم الناس للأسف، وهو مرض الإِمّعِية، \nيعني بيمشي ورا الناس، إذا أحسنوا عمل زيهم وإذا أساؤوا أساء زيهم ، بيقول ما الناس كلها بتعمل كده،\nهو عارف الصح وحكيم ولكن مش قادر يأخذ قرار بإنه يتبع الصح ده، \nفتلاقيه بيدافع عن الباطل و هو عارف إنه باطل، بيمشي مع التيار يعني للأسف وهنا الكارثة\nقام عتبة بن ربيعة يدافع عن الباطل وهو عارف إنه باطل،\nخرج ثلاثة من الأنصار عشان يواجهوا فرسان المشركين عتبة وشيبة والوليد،\nفقالوا لهم:\nاحنا مش عايزينكم إنتم\nاحنا عايزين أبناء عمنا نقاتلهم\nفقال رسول الله ﷺ:\nقم يا عبيدة بن الحارث، قم يا حمزة بن عبد المطلب، قم يا علي بن أبي طالب!\nكل دول من أقارب رسول الله ﷺ\nرسول الله ﷺ كقائد بيورينا بطريقة عملية إنه قبل ما يطلب حاجة خطر من جنوده كان هو مقدم أهله للخطر ده،\nمش بيضحي بالناس عشان هو يبقى مستريح\nكل واحد بدأ يقاتل التاني في النص بين الجيشين، وفي اختلاف في الروايات مين بارز مين، عامة احنا يهمنا النتيجة كانت إيه، علي بن أبي طالب بارز شَيبة، و حمزة بارز عتبة ، وعبيدة بن الحارث بارز الوليد بن عتبة .\nعلي بن أبي طالب وعمه حمزة استطاعا قتل عتبة وشيبة ابنا ربيعة، ومات عتبة ولم تنفعه حكمته \nوعبيدة بن الحارث والوليد بن عتبة كل واحد ضرب الثاني ضربة،\nفراح حمزة وعلي وكملوا على الوليد وقتلاه وأخذا عبيدة ورجعوا لجيش المسلمين،\nوهنا بدأت المعركة وبدأ المسلمين والمشركين يقاتلوا بعض\nهجوم شامل كاسح في كل المواقع، والمسلمين صوتهم بقي يعلي ويقولوا : أحَدٌ أحدْ، أحدٌ أحد، \nالجو بقى مليان تراب من الحركة، أصوات السيوف العالية في كل مكان، ورسول اللهﷺ بيدعي للمسلمين، وبيشجعهم على القتال، ومن تشجيعه إنه قال لهم:\nقوموا إلى جنة عرضها السماوات والأرض، والله إللي يقاتلهم اليوم ويقتل وهو صابر ومحتسب مُقبل غير مُدبر إلا أدخله الله الجنة\nفواحد من الأنصار اسمه عُميْر بن الحمام سمع كلام رسول الله ﷺ وكان في إيده تمرات بياكلها فقال : \nإيه ده يعني مفيش بيني وبين الجنة إلا إن الناس دي يقتلوني؟\nوالله تبقى حياة طويلة لو استنيت لحد ما أكل التمرات دي، ورماها من إيده وانطلق وسط المشركين وقعد يقاتل حتى قُتل شهيد رضي الله عنه، \nفي وسط المعركة وكان عبد الرحمن بن عوف بيقاتل فكان جنبه شابين من شباب الانصار صغيرين في السن،\nهما معاذ ومُعوّذ ابنا عفراء،\nفقال في نفسه ياريت لو كان حوالي ناس أشداء أقوياء \nفلقى واحد منهم جاي يكلمه بصوت واطي جنب أذنه مش عايز صاحبه  يسمع وسأله:\nياعم! إنت تعرف أبو جهل\nفقال له عبد الرحمن بن عوف: وإنت عايز إيه من أبو جهل\nفقال له :أصل أنا سمعت إنه كان بيؤذي ويشتم رسول الله ﷺ فعايز أقتله\nفقال له : أول ما هشوفه هقول لك\nمفيش لحظات إلا والشاب الثاني بيسأل عبد الرحمن بن عوف نفس سؤال صاحبه:\nياعم! تعرف أبو جهل\nفقال له عبد الرحمن بن عوف: وإنت عايز إيه من أبو جهل إنت كمان\nفقال له الشاب: \nأصل أنا سمعت إنه كان بيؤذي ويشتم رسول الله ﷺ فعايز أقتله\nفقال له عبد الرحمن : أول ما هشوفه هقولك \nوقال في نفسه الحمد لله إني وسط الشابين دول\nبعد شوية شاف عبد الرحمن بن عوف أبو جهل وهو وسط المشركين فقال لهما:\nشايفين الرجل إللي حوله الناس ده، هو ده أبو جهل\nفأول ما سمعوا كلامه انطلقا زي السهمين واخترقوا الصفوف لحد ما وصلوا لأبو جهل وكل واحد ضربه بسيفه ورجعوا فورا لرسول الله ﷺ عشان يبشروه\nالمشركين من الصدمة مكنوش عارفين يعملوا إيه ، يلحقوا أبو جهل ولا يطلعوا ورا الشابين، لحد ما وصل الشابين لرسول الله ﷺ وكل واحد فيهم بيقول : يا رسول الله أنا قتلت أبا جهل\nفقال لهما رسول الله ﷺ: إنتم مسحتم سيوفكم؟\nفقالا له : لا، فلما رأى السيفين وشاف عليهم أثر الدم على  قال : إنتم الاثنين قتلتوه\nوالمعركة شغالة ورسول الله ﷺ بيدعي للمسلمين وكان معاه أبو بكر الصديق رضي الله عنه قال رسول الله ﷺ له:\nأبشر يا أبا بكر، فلقد جاء جبريل معه الملائكة ليقاتلوا مع المسلمين\nإيه إللي حصل بعد ما جاءت الملائكة وإزاي انتهت غزوة بدر،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 86, "l": "الجزء 60 | غزوة بدر الكبري الجزء الثاني | انتصار المسلمين في بدر", "u": "https://www.facebook.com/groups/710210019782034/permalink/795275944608774/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الستون\n#غزوة_بدر_الكبرى_الجزء_الثاني\n#انتصار_المسلمين_في_بدر\nاتكلمنا المرة إللي فاتت عن بداية معركة بدر بين المسلمين وبين المشركين،\nوشفنا المبارزة إللي حصلت بين حمزة وعلي وعبيدة ضد عتبة وشيبة والوليد وانتصار المسلمين عليهم\nوربنا أنزل فيهم :\n\"هَٰذَانِ خَصْمَانِ اخْتَصَمُوا فِي رَبِّهِمْ ۖ فَالَّذِينَ كَفَرُوا قُطِّعَتْ لَهُمْ ثِيَابٌ مِّن نَّارٍ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ الْحَمِيمُ\"\nوبدأت المعركة وكان المسلمون ثابتين وأخذوا بالأسباب في مواجهة جيش المشركين، مع إن جزء منهم كانوا كارهين أصلا إنهم يدخلوا في معركة مع المشركين،\nوكان نفسهم يأخذوا القافلة وينتصروا على الأربعين رجل إللي كانوا حارسينها وخلاص،\nلكن لأن ربنا له ترتيب تاني ويريد إنه يظهر الحق ويعلي الإسلام كان لازم تحصل غزوة بدر\n\"كَمَا أَخْرَجَكَ رَبُّكَ مِن بَيْتِكَ بِالْحَقِّ وَإِنَّ فَرِيقًا مِّنَ الْمُؤْمِنِينَ لَكَارِهُونَ\"\nكانت المعركة في السابع عشر من شهر رمضان من السنة الثانية للهجرة،\n وكانت السنة دي أول سنة يُفرض فيها صيام رمضان، وصام رسول الله ﷺ والصحابة معه، لحد ما خرجوا للجهاد فأفطر رسول الله ﷺ وقال للمسلمين إنهم يفطروا عشان يتقوُّوا على الجهاد،\nفأعطاهم الرخصة بالفطر فأفطروا، وده القول الراجح من أقوال العلماء.\nالقتال شغال بين المسلمين والمشركين ورسول الله ﷺ ومعاه أبو بكر الصديق في عريش ،حاجة زي خيمة كده خلف الجيش كان قاعد بيدعو الله إنه ينصر المسلمين،\n☆ممكن حد يسأل إيه ده إزاي رسول الله ﷺ يبقى خلف الجيش كده وسايب المسلمين يجاهدوا لوحدهم، مش المفروض القائد يكون في بينه وبين جنوده تلاحم زي ما قلنا المرة إللي فاتت\nسعد بن معاذ سيد الأنصار وقائدهم هو إللي اقترح على رسول الله ﷺ إنه يعمل له العريش ده ويبقى قاعد فيه،\nومش بس كده ده جهز له جمال سريعة وقال له:\nيا رسول الله! خليك في العريش في أمان ولو ربنا قدر وانهزمنا فترجع إنت للمدينة، \nفالناس لو كانوا يعرفوا إنك خارج تقاتل قريش مكنش حد فيهم تخلّف وكانوا طلعوا معاك،\nوبكده نحافظ على أمر الدعوة وأمر الإسلام،\nفوافق رسول الله ﷺ على اقتراح سعد\nفوقت ما كان المسلمين بيجاهدوا كان رسول الله ﷺ قاعد بيدعي لهم،\nوهو بيدعي جاءته البشرى بمجيء الملائكة عشان تقاتل مع المسلمين،\nفقال رسول الله ﷺ لأبو بكر : \nأبشر يا أبا بكر! فالملائكة جاءت لتقاتل مع المسلمين، وأنا شفت جبريل جاء في جيش من الملائكة وهو لابس لباس الحرب وراكب على فرسه وداخل أرض المعركة والتراب يتصاعد من حول فرسه!\n\"إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُم بِأَلْفٍ مِّنَ الْمَلَائِكَةِ مُرْدِفِينَ\"\nوأول ما جاءته البشارة بالنصر لبس درعه وخرج برة العريش عشان يبشر المسلمين ويحمسهم،\nفي الوقت ده كانت الملائكة دخلت أرض المعركة، كتيبة وراء كتيبة، عشان يقاتلوا مع المسلمين،\n\"وَمَا جَعَلَهُ اللَّهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِ\"\nبدأت الملائكة تقاتل مع المسلمين ،وتفاجأ المسلمين بأحداث غريبة بتحصل\nمنها إن واحد من المسلمين كان بيجري وراء واحد من المشركين عشان يقتله لقاه وقع قبل ما سيفه يوصل له\nومنها برده إن واحد تاني من المسلمين كان وراء واحد من المشركين ومتابعه من بدري عشان يقتله ،فجأة سمع صوت كأن حد بيضرب بالسوط من فوقه وبيقول:\nأقبل حيزوم! يعني تعال يا حيزوم، ونظر الصحابي للمشرك لقاه وقع في الأرض وأنفه اتقطعت ووجهه اتشق كضربة السوط ومكان الإصابة بقى لونه أخضر\nوالصحابة مكنوش يعرفوا إن الملائكة دخلت المعركة وبتقاتل معاهم فلما رجعوا لرسول الله ﷺ وقعدوا يحكوا له فقال لهم إن دي الملائكة جاءت تقاتل وإن ده كان مدد من السماء الثالثة،\nومش بس كده ده المشركين نفسهم شافوا الملائكة، شافوهم على هيئة رجال بِيض راكبين على خيل بَلَق يعني لونها أبيض وأسود بيقتلوا الناس ويأسروهم،\nمين كمان شاف الملائكة\nالشيطان، إللي كان متجسد في صورة سراقة بن مالك عشان يدفع الناس إنهم يخرجوا لحرب المسلمين،\nأول ما الشيطان شاف الملائكة خاف ورجع للوراء عشان يهرب، شافه واحد من المشركين قال له:\nعلى فين يا سراقة إنت مش قلت إنك هتحمينا من قبيلة بني بكر؟\nفقال لهم :\nأنا شايف إللي إنتم مش شايفينه وهرب من أرض المعركة\nوأنزل الله:\n\"وَإِذْ زَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ الْيَوْمَ مِنَ النَّاسِ وَإِنِّي جَارٌ لَّكُمْ ۖ فَلَمَّا تَرَاءَتِ الْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّي بَرِيءٌ مِّنكُمْ إِنِّي أَرَىٰ مَا لَا تَرَوْنَ إِنِّي أَخَافُ اللَّهَ ۚ وَاللَّهُ شَدِيدُ الْعِقَابِ\"\n☆ودي عادة الشيطان، يقعد يغري بني آدم ويزين لهم الغلط والحرام لحد ما يقعوا فيه وبعدين يقعد يندّم فيهم ويخليهم ييأسوا من رحمة ربنا ويؤجلوا التوبة لحد ما يموتوا ويدخلوا النار،\nوهيقف الشيطان في النار والناس تقعد تلومه إن هو إللي أغراهم وإنه السبب في إنهم دخلوا النار فهيرد عليهم ويقول لهم:\nربنا وعدكم الوعد الحق، وأنا وعدتكم وأغريتكم، فإنتم تركتم وعد ربنا واتبعتوني، مع إن أنا كل إللي عملته إني دعيتكم، وإنتم إللي سمعتم الكلام، يعني أنا مضربتكوش على إيدكم عشان تسمعوا كلامي،\nفمحدش يلومني أنا ولوموا أنفسكم، حد قال لكم تسمعوا كلامي\n\"وَقَالَ الشَّيْطَانُ لَمَّا قُضِيَ الْأَمْرُ إِنَّ اللَّهَ وَعَدَكُمْ وَعْدَ الْحَقِّ وَوَعَدتُّكُمْ فَأَخْلَفْتُكُمْ ۖ \nوَمَا كَانَ لِيَ عَلَيْكُم مِّن سُلْطَانٍ إِلَّا أَن دَعَوْتُكُمْ فَاسْتَجَبْتُمْ لِي ۖ فَلَا تَلُومُونِي وَلُومُوا أَنفُسَكُم\"\n☆وطبعا السؤال إللي بيفرض نفسه هنا، إزاي الشيطان تجسد في صورة سراقة وهو المفروض إنه متسلسل لأن الغزوة كانت في رمضان والشياطين في رمضان بتكون مقيدة\n◇أولا : إللي بيتسلسل في رمضان مَردة الجن، يعني الجن الأقوياء وإللي لهم أثر، \nأما الشياطين العاديين فعادي موجودين، وكمان صفيد الشياطين وحبسهم بيكون في حق المؤمنين الصائمين إللي حافظوا على شروط صيامهم ووآدابه، مش الكفار والشيطان كان مع الكفار،\n◇ثانيا: \nمفيش دليل بيقول إن تصفيد الشياطين يعني تقييدهم كان في أول تشريع الصوم، ممكن كان بعد كده، فكان عادي إن الشيطان كان يبقى مع المشركين في بدر\nالمشركين بدأوا ينهزموا ويفروا بصورة عشوائية غير منظمة وهم مرعوبين وتوجهوا ناحية مكة، \nوانتصر المسلمون وبدأوا يجمعوا الغنائم ويأسروا إللي يشوفوه من المشركين،\nوهنشوف دلوقتي مين إللي أُسر من المشركين، لكن قبل كده\n☆عندنا سؤالين مهمين\n◇السؤال الأول: \nجبريل عليه السلام بطرف جناحه فقط دمّر قُرى قوم لوط كلهم، إزاي بقى هو ييجي في ألف ملك من الملائكة عشان يقاتلوا ألف واحد من المشركين وهو قادر إنه يهزم كل المشركين مرة واحدة\nجيش الملائكة كان جاي على هيئة مدد لجيش المسلمين، يعني كأنهم جيش تاني جاي يساعدهم على القتال،\nفجاءوا على صورة البشر، على خيل ولابسين لبس الحرب، \nيعني جاءت بقوة قريبة من قوة البشر،\nعشان يكون رسول الله ﷺ والمسلمين إللي معاه هم إللي بيقاتلوا، ويكونوا سبب مباشر في الانتصار على المشركين، وميكونش النصر مجرد معجزة إلاهية خاااالصة زي نصر نوح عليه السلام على قومه بالطوفان مثلا،\nلأن أمة الإسلام بتعتمد على الجهاد في نشر الدين ومفيش سنة إهلاك عامة بمعجزة خالصة من عند الله زي الأمم السابقة\nيعني من الآخر كأن جيش الملائكة ده =إذا صح التعبير يعني= عامل زي الأسلحة المتطورة إللي بتساعد الجنود في المعركة\nده غير إن الملائكة كان لها دور في تثبيت المؤمنين ورفع روحهم المعنوية وخصوصا إن كان في ناس من الصحابة مكنوش عايزين يقاتلوا المشركين وكانوا عايزين القافلة زي ما قلنا من شوية،\n\"إذْ يُوحِي رَبُّكَ إِلَى الْمَلَائِكَةِ أَنِّي مَعَكُمْ فَثَبِّتُوا الَّذِينَ آمَنُوا ۚ سَأُلْقِي فِي قُلُوبِ الَّذِينَ كَفَرُوا الرُّعْبَ فَاضْرِبُوا فَوْقَ الْأَعْنَاقِ وَاضْرِبُوا مِنْهُمْ كُلَّ بَنَانٍ\"\n◇وده يأخذنا للسؤال الثاني :\nطيب معنى كده إن الملائكة هي إللي انتصرت والمسلمين مكنش لهم لازمة وأخذوا النصر على الجاهز\nطبعا لأ، لأن لو كان ده حصل كان ربنا أنزل الملائكة من بداية المعركة وخلصنا، لكن الملائكة نزلت بعدييين، بعد ما حصلت المبارزة والتقى الجيشين،\nوبعد ما كان حمزة بيقاتل المشركين ويقتلهم وكان ثابت في أرض المعركة، \nوبعد ما عُمير بن الحمام انطلق وسط المشركين يقاتلهم، وبعد ما عوف بن الحارث قام وخلع درعه وقعد يقاتل لحد ما استشهد، بعد ما كان سأل رسول الله ﷺ عن الحاجة إللي بتجعل ربنا يضحك من عبده فقال له رسول الله ﷺ:\nإنه يجاهد العدو وهو مش لابس درع\n☆ملحوظة مهمة :\nمن صفات ربنا إنه بيضحك يا جماعة عادي جدا، يعني رسول الله ﷺ وهو أعلم الناس عن ربه ،أثبت لربنا صفة الضحك عشان بس الناس إللي بتقعد تقول إنتم إزاي تقولوا على ربنا بيضحك وتشبهوه بالبشر\nهو احنا مش بنشبه ربنا بالبشر ولا بغيره، احنا بنُقر الصفة إللي ربنا وصف نفسه بها سبحانه، بيضحك أه بيضحك إزاي منعرفش وهنا نقف\n\"لَيْسَ كَمِثْلِهِ شَيْءٌ ۖ وَهُوَ السَّمِيعُ الْبَصِيرُ \"\nزي ما قلنا قبل كده أنا بقول رجل الكرسي، وبقول رجلي، هل رجلي زي رجل الكرسي ولّا مختلفة؟\nأهه ولله المثل الأعلى الوضع كده مع ربنا، بنتشارك في الكلمة فقط، لكن صفة الضحك بتاعتنا مختلفة عن صفة الضحك بتاعة ربنا تماما\nفكانت الملائكة جند من جنود الله إللي أرسلهم عشان يساعدوا المسلمين، زي كده جندي النوم إللي ربنا أرسله على المسلمين قبل المعركة، \nوزي جندي الرعب إللي ربنا بيقذفه في قلوب أعداء الإسلام، وغيرها وغيرها من جنود ربنا \nانتصر المسلمون في بدر وقُتل من المشركين سبعين رجل، وأسر المسلمون سبعين رجل،\nمن الناس إللي أُسرت أُمية بن خلف، فاكرينه\nإللي رسول الله ﷺ قال إن المسلمين هيقتلوه،\nلما لقى المسلمين انتصروا كان عايز يهرب بس معرفش، \nفقال بدل ما أهرب والمسلمين يلحقوني ويقتلوني خليني أستنى هنا أنا وابني وأشوف واحد ياخدني أسير وبعدين أبقى أفدي نفسي،\nعدى عليه عبد الرحمن بن عوف وكان يُسمى في الجاهلية عبد عمرو، فكان لما أمية بن خلف بينده عليه ويقول له يا عبد عمرو مكنش بيرد عليه ويقول له: \nقل لي عبد الرحمن، \nفكان أمية يقول له انا معرفش مين الرحمن ده، فقال له عبد الرحمن كل مرة هتنده علي بعد عمرو مش هرد عليك\nفقال له أمية : طيب خلينا نتفق على اسم،\nفاتفقوا على عبد الإله، فلما أمية بن خلف شاف عبد الرحمن بن عوف نادى عليه:\nيا عبد عمرو!!\nفعبد الرحمن مردش عليه\nفقال له أمية : يا عبد الإله!\nفرد عليه عبد الرحمن وقال له : عايز إيه؟\nقال له أمية : إيه رأيك أعطيك حاجة أحسن من إللي في إيدك ده؟\nوكان في يد عبد الرحمن بعض الدروع أخذها من أرض المعركة كغنائم، \nفقال له عبد الرحمن بن عوف: أكيد طبعا!\nفرمى عبد الرحمن الدروع إللي كانت في إيده، فأخذه هو وابنه أسيرين، وأخذهما لحد ما راح بهم لمكان آمن، لحد ما الأمور تهدأ ويروح بهما لرسول الله ﷺ،\nلما بعدوا ووصلوا عند جبل بعيد عن أرض المعركة ارتاح أمية بن خلف، وهدأت نفسه، \nمتخيلين بقاله كم يوم أعصابه مشدودة خايف من الموت،\n إللي قال عن رسول الله ﷺ إنه هيحصل، فمصدق بقى إنه أخذ نفسه وخلاص نجى من القتل،\nلدرجة إنه قعد يتكلم مع عبد الرحمن بن عوف عادي خالص بيدردشوا وسأله أمية :\nيا عبد الإله هو مين الرجل إللي كان على صدره ريشة نعامة ده\nفقال له عبد الرحمن :أه ده حمزة! \nفقال له أمية: ده عمل فينا عمايل \n☆هم طبعا عارفين حمزة لكن لأنهم كانوا لابسين الخوذة إللي بتغطي الوجه دي فمكنوش عارفين الأشخاص بالضبط\nوكملوا مشي مع بعض وفجأة يسمع أمية بن خلف حد بيصرخ صرخة شديدة رعبت أمية بن خلف من تاني\nالصرخة كانت من أعماق انسان مضطهد شاف العذاب ألوان، ولعل أثار التعذيب لسه موجودة على جسمه،\nكان الصارخ بلال بن رباح إللي كان بيعذبه أمية بن خلف، صرخ بلال أول ما شاف أمية وقال:\nرأس الكفر أمية بن خلف! لا نجوت إن نجا، يعني يا أنا يا هو\nوبدأ ينادي بأعلى صوته يا أنصار الله رأس الكفر أمية بن خلف، ووقف يكلم بعض الأنصار فأخذ عبد الرحمن بن عوف أمية عشان ينقذه منهم وقعد يقول لهم ده أسيري محدش له دعوة بيه، وهم مش مقتنعين، \nده لازم يُقتل مينفعش يكون أسير، فترك عبد الرحمن بن عوف ابن أمية وراه عشان يلهيهم به لحد ما يهرّب أبوه فقتلوه وطلعوا وراهم عشان يقتلوا أمية، وكان أمية رجل ثقيل، تخين يعني\nفقال له عبد الرحمن : نام في الأرض، فنام أمية ونام عليه عبد الرحمن وقعد يقول لهم سيبوه، ده أسيري، فمسمعوش كلامه وقعده يطعنوا أمية من تحت عبد الرحمن بن عوف  بسيوفهم لحد ما قتلوه\nفكان يقول كل ما يفتكر الموقف ده:\nرحم الله بلال ضيع علي دروعي وأسيري\nناس تانية من المشركين أُسرت وكان لهم قصة هنعرفها الجزء الجاي إن شاء الله"}, {"n": 87, "l": "الجزء 61 | قتلي واسري بدر", "u": "https://www.facebook.com/groups/710210019782034/permalink/795291514607217/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الواحدة_والستون\n#قتلى_وأسرى_بدر\nاتكلمنا المرة إللي فاتت عن غزوة بدر وعن الأحداث إللي حصلت مع المسلمين وإزاي إنهم ثبتوا في قتالهم ضد المشركين فربنا أرسل لهم مدد من الملائكة عشان يقاتلوا معهم ويثبتوهم، وانهزم المشركون وهربوا من أرض المعركة واتجهوا نحو مكة،\nقُتل من المشركين في غزوة بدر سبعون رجل، وأُسر سبعون،\nمن السبعين إللي قُتلوا غير عتبة وابنه الوليد وشيبة أخو عتبة قُتل حنظلة بن أبي سفيان وإللي قتله زيد بن حارثة إللي كان في الوقت ده اسمه زيد بن محمد،\nوقُتل أبو البُخْتري بن هشام مع إن رسول الله ﷺ قال لو رأيتم أبو البختري بن هشام في المعركة محدش يقتله،\nمن باب حفظ الجميل له،\nفاكريييين الناس إللي شاركت في نقض الصحيفة في شعب أبي طالب وكان أبو البختري واحد منهم\nأهه رسول الله ﷺ كان عايز يرد جميل أبو البختري بن هشام فقال للمسلمين محدش يقتله،\nلكن أبو البختري كان بيقاتل واحد من المسلمين فقال له المسلم رسول الله ﷺ أمر إننا لا نقتلك فخليك على جنب وكان أبو البختري معاه واحد صاحبه فقال للمسلم : \nطيب وصاحبي\nفقال له الصحابي : صاحبك لأ، معندناش أمر بعدم قتله،\n فقام أبو البختري يدافع عن صاحبه ويقاتل المسلم فاضطر الصحابي إنه يدافع عن نفسه فقاتل أبو البختري بن هشام فقتله\nوبعدين اعتذر لرسول الله ﷺ وقال له إنه اضطر يدافع عن نفسه فسامحه رسول الله ﷺ، \nمن الناس إللي قُتلت كمان نوفل بن خويلد أخو أم المؤمنين خديجة بنت خويلد، وإللي قتله علي بن أبي طالب\nوعمر بن الخطاب قتل خاله العاص بن هشام بن المغيرة أخو أبو جهل، \nوعبد الرحمن بن أبي بكر الصديق مكنش لسه أسلم فكان بيقول لأبوه بعد إسلامه أنا شفتك في غزوة بدر وكنت ببعد عنك عشان مقتلكش،\nفقال له أبو بكر الصديق رضي الله عنه أنا لو كنت شفتك كنت قتلتك\n☆لازم نقف هنا وقفة مهمة جدا\nالصحابة كانوا بيقتلوا أقاربهم بكل بساطة عادي كده إزاي؟\nهم مش كان بينهم ذكريات وعيش وملح وعلى طول مع بعض واحنا عارفين العصبية القبلية عندهم كانت عاملة إزاي،\nودلوقتي كده بكل بساطة يقتلوا أقاربهم!\nلأ والأب يقول لابنه أنا لو كنت شفتك كنت قتلتك كده عادي\nانتم عارفين إن في شريعة الإسلام على قول جمهور أهل العلم إن الأب لا يُقتل قصاصا لو قتل ابنه،\n وده لأن مفيش أب عاقل هيقتل ابنه في الوضع الطبيعي،\nبقول في 《الوضع الطبيعي》 \n وإلا في حالات يُقتل الوالد بابنه\nلأن الأب مفطور على حبه لابنه يعني عاطفة لا إرادية،\nفإزاي وصل بأبي بكر الصديق رضي الله عنه إنه يقول لابنه أنا كنت هقتلك لو شفتك،\nوالناس دي مكنتش بتهوّل ولا تقول كلام كده وخلاص، كانوا على أد كلمتهم فعلا\nوشوفوا مصعب بن عمير هو كمان في قصته مع أخوه لما أُسر قال للي أسره وكان واحد من الأنصار:\nامسكه كويس وخد بالك منه، أمه غنية وعندها فلوس كتير هتفديه بيها\nفأخوه قال له: هي دي وصيتك بأخوك\nفقال له مصعب وهو بيشاور على الأنصاري : هو إللي أخويا مش إنت\n《قصة مصعب مع أخيه فيها ضعف بسيط》 \nلكن بتؤدي نفس المعنى، إن الصحابة بقى انتماؤهم لدينهم، وإن صلة القرابة دي لا تعني لهم أي شيء وإن أهم حاجة هي الدين،\nفي حين إن في الواقع بتاعنا تلاقي البنت مثلا تحضر فرح أخوها ولّا فرح أختها ولا أي حد من قرايبها إللي كله منكرات ومحرمات بحجة إن دي أختي وإزاي أسيبها في يوم زي ده،\nوده أخويا إزاي محضرش فرحه\nده هيزعل والناس هتزعل وأمي وأبويا و...و...\nطيب هو انتم متخيلين إن الناس إللي احنا عصينا ربنا عشانهم دول هينفعونا يوم القيامة\nمتخيلين إن واحد فيهم هييجي يقول لربنا يارب سامحه أصله عصاك عشان ميزعلنيش\nعارفين أهلنا دول هيعملوا إيه معانا يوم القيامة؟\nمش أنا إللي هقولكم شوفوا ربنا عالم الغيب والشهادة بيقول لنا إيه إللي أهلنا أو أبنائنا أو أي حد هيعمله معانا  يوم القيامة:\n\"يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ ۩ وَأُمِّهِ وَأَبِيهِ۩ وَصَاحِبَتِهِ وَبَنِيهِ۩لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ\"\nهيطلعوا يجروا مننا ومحدش فيهم هينفعنا ولا يعطينا حسنة واحدة، \nهو لما يبقى حد فينا عنده امتحان والأم أو الأب قالوا لك متذاكرش وسيبك من المذاكرة والكلام ده هتسمع كلامهم؟ ولّا هنقعد نذاكر لأننا هنبقي محتاسين في الإمتحان ومش عارفين نجاوب حاجة\nأنا عارف إنهم مش بيقولوا كده بالعكس ده هم مش وراهم طول النهار غير قوم ذاكر قوم ذاكر\nولو كان الأهل حريصين الحرص ده على آخرة عيالهم زي ماهم حريصين على دنيتهم مكنش ده بقى حال الشباب\nفاحنا نخلينا حريصين على مصلحة نفسنا، \nمحدش هينفعنا يوم القيامة عند ربنا غير عملنا الصالح، غير كده كله هيهرب مننا\nمن الناس إللي قُتلت يوم بدر القائد العام للمشركين أبو جهل عمرو بن هشام، قلنا إن معاذ ومعوّذ ابنا عفراء هم إللي قتلوه وأخذا سيفيهما وذهبا لرسول الله ﷺ، \nفي الوقت ده كان أبو جهل سقط على الأرض ولسه فيه روح وفضل عايش لحد ما المسلمين انتصروا،\nعبد الله بن مسعود الصحابي كان ماشي في أرض المعركة فشاف أبو جهل وهو واقع في الأرض الدم بينزل منه،\nفوضع رجله على رقبة أبي جهل وكان أبو جهل آذى عبد الله بن مسعود بعد ما أسلم وضربه، فقال له عبد الله بن مسعود:\nهل أخزاك الله يا عدو الله؟\nيعني شوفت ربنا عمل فيك إيه \nفقال له أبو جهل :\nأخزاني إزاي يعني ولا عمل فيّ إيه، محصلش حاجة غير إنكم قتلتوني\nقول لي إنت بس الغلبة لمين\nفقال له عبد الله بن مسعود :\nالغلبة لله ولرسوله يا عدو الله\nوراح عبد الله بن مسعود  طالع على صدره فقال له أبو جهل:\nلقد ارتقيت مُرْتقًا صعبا يا رُوَيْعِيّ الغنم\nيعني إنت في مكان عالي أوي متستاهلش إنك تكون فيه،\n☆إيه رُوَيْعي الغنم دي \nعبد الله بن مسعود كان من أوائل الناس إللي أسلموا وكان سنه صغير لما أسلم، كان في يوم من الأيام بيرعى غنم لواحد من سادات مكة اسمه عقبة بن أبي مُعيط، \nفعدى عليه رسول الله ﷺ وكان معاه أبو بكر الصديق رضي الله عنه وقال له رسول الله : معاك لبن؟\nفقال له عبد الله بن مسعود:\nأيوة معايا ولكني مؤتمن، يعني الغنم ده عندي أمانة \nفقال له رسول الله ﷺ: \nطيب هل عندك شاة لسه صغيرة لم ينزل عليها الفحل، يعني لسه متجوزتش\nفجاء له بشاة صغيرة فمسح رسول الله ﷺ على ضرعها وقعد يحلبها ونزل منها اللبن فشرب رسول الله ﷺ وشرب أبو بكر الصديق وسقى عبد الله بن مسعود،\nوبعدين قال رسول الله ﷺ للضرع : تقلص، يعني ارجع مكانك فرجع،\nوبعد الموقف ده راح عبد الله بن مسعود لرسول الله ﷺ وقال له : علمني من الكلام إللي بتقوله ده، القرآن يعني\nفمسح رسول الله ﷺ على رأسه وقال : \nإنك غلام مُعلّم\nوأسلم عبد الله بن مسعود من ساعتها وكان من أول من جاهر بإسلامه وبقراءة القرآن في مكة وكان يُؤذى ويُضرب مع المسلمين المستضعفين،\nعبد الله بن مسعود كان قصير ورفيع جدا لدرجة إن الهواء كان بيحرك رجله لو طلع على نخله،\nوكانت بشرته سوداء وكان من أجود الناس وأطيبهم ريحا،\nوكان ملازم لرسول الله ﷺ وكان بيخدمه.\nفأبو جهل بيقول له رُويعي الغنم تصغير كلمة راعي الغنم تحقيرا لعبد الله بن مسعود رضي الله عنه، \nوخصوصا مع جسمه الصغير وضخامة جسم أبو جهل بالنسبة له،\nيعني أبو جهل حتى وهو بيموت كان الكبر والغرور ماليه\nده فرعون إللي قال انا ربكم الأعلى لما شاف الموت قال آمنت بإله بني إسرائيل، \nلكن ده حتى في نهاية حياته وبعد ما خلاص شاف إنه اتغلب والمسلمين انتصروا وبعد كل الأحداث دي المفروض إنه يلين ولا على الأقل يعمل زي فرعون ،لكن ده ولا الهوا \nعبد الله بن مسعود بسيفه راح قاتل أبو جهل \nأبو جهل كان عايز يأتي ماء بدر ويشرب الخمر ويسهر ويعمل حفلة والراقصات والمغنيات يغنوا ويرقصوا ويسمع العرب كلهم بقوة مكة،\nعشان محدش يتجرأ ويفكر يعتدي على قوافل مكة، \nأهه ربنا دفنه فيها، ودي نهاية أي واحد بيحارب ربنا وبيحارب دينه\n☆في روايات بتقول إن عبد الله بن مسعود رضي الله عنه قطع رأس أبو جهل وأخذ رأسه وراح بها لرسول الله ﷺ وقال له إن دي رأس أبو جهل، \nفرسول الله ﷺ استحلف عبد الله بن مسعود بالله دي رأس أبو جهل فكان عبد الله بن مسعود بيؤكد الكلام،\nكل الروايات إللي فيها قصة قطع الرأس دي روايات ضعيفة،\nملقتش منها ولا حتى حديث حسن \nوخصوصا إن مش من هدي المسلمين حمل الرؤوس من مكان لمكان،\nوحتى بعدين في خلافة أبي بكر الصديق رضي الله عنه لما واحد من أصحابه جاء له برأس كافر مقطوع فأنكر عليه أبو بكر، فقال له صاحبه : \nطيب ما فارس والروم بيعملوا كده\nفقال له أبو بكر: يعني احنا هنتبع سنة فارس والروم؟\nيكفي إنك تكتب لي أو تخبرني بالخبر إنك قتلته\nفاللي يهمنا إن أبو جهل عدو الإسلام الأول قُتل، عقبال الباقي يارب\nنيجي بقى للأسرى، أسر المسلمون في غزوة بدر سبعين رجل من المشركين،\nكان منهم العباس بن عبد المطلب عم رسول الله ﷺ وكان رسول الله ﷺ قال للمسلمين لو حد فيكم رأى العباس لا يقتله فهو خرج مُكرها،\nويُقال إن واحد من الصحابة وهو ابن عتبة بن ربيعة إللي قُتل في المبارزة في بداية المعركة لما سمع كده قال :\nيعني أنا أبويا يُقتل ونسيب العباس، والله لو شفته لأضرب وجهه بالسيف،\nالقصة دي ضعيفة لا تصح \nأصلا يعني بالعقل مفيش صحابي مؤمن خالص الإيمان يعترض على كلام رسول الله ﷺ بالطريقة دي\nواحنا شفنا من شوية إزاي المسلمين أصلا كان عادي عندهم يقتلوا ويأسروا أقاربهم،\nوالصحابة عارفين كويس أوي إن رسول الله ﷺ لا ينطق عن الهوى فمعنى إنه قال كده يبقى أكيد في سبب، \nفمش هيعصوا أمر رسول الله ﷺ بالطريقة دي، وفعلا العباس هيسلم بعدين زي ما هنشوف\n☆طيب ممكن حد أصلا يقول اشمعنى رسول الله ﷺ ميرضاش لعمه المشرك إنه يُقتل، ويرضى إن ناس تانية يقتلوا \n◇أولا: زي ما قلنا العباس خرج مُكره، يعني مكنش عايز يقاتل،\n◇ثانيا : رسول الله ﷺ دائما يكافئ إللي عمل معاه معروف، احنا شفنا إنه قال لأصحابه محدش يقتل أبو البختري بن هشام من باب رد الجميل،\nوالعباس كان بيعاون رسول الله ﷺ ويدافع عنه ويقف معاه قبل الهجرة حتى إنه حضر بيعة العقبة الثانية زي ما شفنا،\nفلو هنقول إنه من باب رد الجميل يبقى عادي إنه يأمر بعدم قتله،\nوحتى وصل برسول الله ﷺ الإمتنان والعرفان بالجميل إنه قال : لو المطعم بن عدي كان عايش وطلب مني الأسرى دول يأخذهم بدون فداء كنت أعطيتهم له\nفاكرين المطعم بن عدي؟\nكان واحد من إللي نقضوا الصحيفة بتاعة شعب أبي طالب وكمان هو الوحيد إللي رضي يحمي رسول الله ﷺ بعد ما رجع من الطائف،\nفرسول الله ﷺ كان لا ينسى للناس فضلهم ومعروفهم، \nوفي نفس الوقت يكون عادل معاهم،\nِيعني رسول الله ﷺ أه أمر إن العباس لا يُقتل لكن لم يُعْفِه من المسؤولية كاملة،\nفلما جاء الأنصاري إللي أسر العباس لرسول الله ﷺ وهو ماسك العباس في إيده رسول الله ﷺ سأله:\nإنت إزاي أسرته؟! فقال الأنصاري: واحد مشفتش زيه قبل كده ساعدني في أسره\nفقال له رسول الله ﷺ: أعانك على أسر العباس ملك كريم\nفقال رسول الله ﷺ للعباس:\nيا عباس افدي نفسك وابن أخوك عقيل بن أبي طالب ونوفل بن الحارث وحليفك عتبة بن جَحْدم!\nفالعباس رفض وقال لرسول الله ﷺ :\nأنا كنت مسلم قبل المعركة، وهم خلوني أخرج غصب عني \nفرسول الله ﷺ قال له: الله أعلم بحالك، لو كنت صادق ربنا هيجزيك بإسلامك، لكن إللي ظاهر لنا إنك مشرك فافدِ نفسك\nفقال العباس لرسول الله ﷺ: طيب يارسول الله احسب فدائي من الفلوس إللي إنت أخذتها مني\nوكان رسول الله ﷺ أخذ منه عشرين أوقية من الذهب غنيمة، والأوقية في العهد النبوي كانت حوالي ثلاثين إلا ربع جرام من الذهب،\nفالعباس بيقول احسب فدائي من الذهب ده، فرسول الله ﷺ رفض وقال له:\nدي حاجة ربنا أعطاها لنا منك، متدخلش في الفداء\nفقال له العباس: طيب أنا معنديش مال \nفقال له رسول الله ﷺ:\nأمال فين المال إللي خبيته في مكة قبل ما تخرج للقتال وقلت لزوجتك أم الفضل لو أنا حصل لي حاجة في سفري ده فأعطي عبد الله كذا وأعطي الفضل كذا؟!\n☆كان بيقول لها توزع الميراث إزاي يعني \nفقال العباس لرسول الله ﷺ: والذي بعثك بالحق محدش يعرف الموضوع ده غيري أنا وهي، وأنا عارف إنك رسول الله حقا\n¤خليني أقول لكم مين هي أم الفضل دي، ما أنا مش هتفاجئ لوحدي\nأم الفضل زوجة العباس تبقى :\n♡خالة خالد بن الوليد\n♡أخت أم المؤمنين زينب بنت خُزيمة\n♡وهي أخت الصحابية أسماء بنت عميس زوجة جعفر بن أبي طالب\n♡وهي أخت أم المؤمنين ميمونة بنت الحارث\nوكانت من أوائل من أسلم من النساء \nهنشوف لها موقف بعدين مع أبو لهب بس خلونا نكمل قصة باقي الأسرى،\nمن إللي أُسروا يوم بدر النضر بن الحارث وعقبة بن أبي معيط وسهيل بن عمرو،\nالنضر بن الحارث فاكرينه\nإللي كان بيقول : محمد أحسن مني في إيه، هو يحدث بأساطير وأنا احدث بأساطير،\nوإللي نزل فيه :\n\"إِذَا تُتْلَىٰ عَلَيْهِ آيَاتُنَا قَالَ أَسَاطِيرُ الْأَوَّلِينَ \"\nوكان راح مع عقبة بن أبي مُعيط لليهود عشان يسألوه عن رسول الله ﷺ فقال لهم اليهود اسألوه عن ذي القرنين والفتية إللي اتكلمنا عنهم قبل كده\nوعقبة بن أبي معيط ده في رواية إنه أسلم ولما صاحبه أمية بن خلف عرف إنه أسلم وكان بيحبه جدا،\nلما رجع من تجارة في الشام وجاء عقبة يكلمه مردش عليه قال لأمية: مالك في إيه، \nفقال له أمية مش هكلمك أبدا ولا انت صاحبي ولا أعرفك إلا لما تروح تشتم محمد وتبصق في وجهه،\nفراح فعلا وشتم رسول الله ﷺ وحاول يبصق في وجهه لكن ربنا لم يسلطه على رسول الله ﷺ، \nونزل فيه قول الله عز وجل:\n\"وَيَوْمَ يَعَضُّ الظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَا لَيْتَنِي اتَّخَذْتُ مَعَ الرَّسُولِ سَبِيلًا۩يَا وَيْلَتَىٰ لَيْتَنِي لَمْ أَتَّخِذْ فُلَانًا خَلِيلًا۩\nلَّقَدْ أَضَلَّنِي عَنِ الذِّكْرِ بَعْدَ إِذْ جَاءَنِي ۗ وَكَانَ الشَّيْطَانُ لِلْإِنسَانِ خَذُولًا\"\nأهم الإثنين بقوا في أيدي المسلمين أسرى\nنظر رسول الله ﷺ للنضر بن الحارث نظرة شاف فيها الموت\nفقال النضر لمصعب بن عمير وكان أقربهم منه من ناحية الرحم :\nكلم صاحبك إنه يعاملني زي باقي أصحابي، لو معملتش كده والله ليقتلني\nفقال له مصعب : \nإنت كنت بتقول عن كتاب ربنا كذا وكذا وبتقول عن رسول الله ﷺ كذا وكذا، وكنت بتعذب أصحابه\nفقال له النضر :\nلو قريش كانت أسَرتك مكنش حد يقدر يقتلك وأنا حي\nفقال له مصعب:\nكلامك صحيح، لكن أنا غيرك، الإسلام قطع بيننا العهود دي\nفأمر رسول الله ﷺ علي بن أبي طالب إنه يقتل النضر بن الحارث 《صبرًا》\nوأمر رسول الله ﷺ عاصم بن ثابت إنه يقتل عقبة بن أبي معيط هو كمان 《صبرًا》،\nومعنى يُقتل صبرا إن الإنسان يُقتل في غير معركة أو حادثة، \nيعني نجيب شخص كده ونقتله وهو ينظر،\nده معنى إن الإنسان يقتل صبرا،\nفلما رسول الله ﷺ أمر إن عقبة يُقتل قال لرسول الله ﷺ:\nإنت هتقتلني أنا لوحدي دونا عن قريش كلها\nيقصد من السبعين الأسرى،\nفقال له رسول الله ﷺ: نعم\nفقال : اشمعنى أنا إللي أُقتل من بين قريش كلهم\nفقال له رسول الله ﷺ : لعداوتك لله ورسوله!\nوتوجه رسول الله ﷺ للصحابة وقال لهم: عارفين ده عمل في إيه؟!\nكنت مرة ساجد عند الكعبة فجاء ووضع رجله على رقبتي وقعد يضغط عليّ لحد ما حسيت إن عيني هتطلع من مكانها!\nومرة ثانية جاء بأمعاء بعير ورماها على رأسي وأنا ساجد فجاءت فاطمة وغسلته عن رأسي\nوقُتل عقبة بن أبي معيط،\n☆في ناس بتستغل الحادثتين دول عشان يطعنوا في الإسلام ويقولوا إن المسلمين كانوا متعطشين للدماء وإزاي يقتلوا اثنين من الأسرى\nطيب ماهو يا أذكى إخواتك لو كان المسلمين متعطشين للدماء كانوا قتلوا السبعين كلهم، مش اثنين بس\nثم أصلا حكم الأسرى في الإسلام حاجة من ثلاثة إما إن الحاكم يتفضل على الأسير ويطلق سراحه بدون أي أموال يفتدي بها نفسه،\nأو يأخذ منه أموال يفتدي بها نفسه، أو يقتله، \nفالحاكم هو إللي يختار المناسب من الإختيارات الثلاثة دي على حسب المصلحة\nأمر رسول الله ﷺ المسلمين إنهم يُحسنوا للأسرى إللي معاهم، فكانوا بيعطوهم الخبز، وكان أحسن الطعام معاهم وياكلوا هم التمر،\nويركّبوا الأسرى على الإبل والمسلمين إللي يمشوا، \n☆وفي هنا رواية عن عمر بن الخطاب رضي الله إنه كان عايز ينزع أسنان سهيل بن عمرو الأسير عشان ميخطبش ضد رسول الله ﷺ ويهجوه مرة ثانية، فرسول الله ﷺ رفض وقال له لعل سهيل يقف موقفا تشكره عليه... إلى آخر القصة.\nالقصة دي غير صحيحة إطلاقا \nكل الأحاديث بتاعة القصة دي ضعيفة\nانتشرت الأخبار في الجزيرة العربية بهزيمة قريش على أيدي المسلمين، إيه رد فعل أهل مكة على الهزيمة؟\nوكان إيه رد فعل أهل المدينة لما عرفوا بهزيمة قريش؟\nده إللي هنعرفه الجزء الجاي إن شاء الله\n☆"}, {"n": 88, "l": "الجزء 62 | رد فعل الناس علي نصر المسلمين", "u": "https://www.facebook.com/groups/710210019782034/permalink/795305741272461/", "t": "هل يجوز  نقرأ الفاتحه ع الميت  طب الميت بيسمع كلامنا \n اقرئو وانتو  هتعرفو\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثانية_والستون\n#إني_وجدت_ما_وعد_ربي_حقا\n#رد_فعل_الناس_على_نصر_المسلمين\nاتكلمنا المرة إللي فاتت عن أسرى وقتلى غزوة بدر، وبدأت أخبار انتصار المسلمين على مشركي مكة تنتشر في جزيرة العرب، وكان رسول الله ﷺ من عادته إنه إذا انتصر على جيش يقعد في مكان المعركة ثلاثة أيام،\nعشان يريحوا وعشان يظهر قوته ويخافه الأعداء ويدفن شهداء المسلمين،\nوكانوا أربعة عشر رجلا من المسلمين، والصحيح إن الشهيد يُدفن في مكانه إللي قُتل فيه ولا يُغسل، وحتى الصلاة عليهم غير واجبة لأن مفيش أحاديث تُثبت أو تنفي صلاة رسول الله ﷺ على الشهداء في غزوة من الغزوات.\nوصل خبر انتصار المسلمين إلى أهل مكة عن طريق واحد من قبيلة خزاعة،\nأول ما دخل مكة الناس سألته : إيه الأخبار\nفقال لهم: قُتل عتبة بن ربيعة وقُتل شيبة بن ربيعة وأبو الحكم بن هشام، وأمية بن خلف،\nوقعد يعد لهم سادات مكة إللي قُتلوا، فسمعه صفوان بن أمية بن خلف فقال لهم:\nالرجل ده شكله اتجنن، اسألوه كده عني شوفوا هيقول إيه\nفلما سألوه عن صفوان قال لهم : ماله صفوان ماهو قاعد عند الحِجر\nوأنا والله شفت أبوه وأخوه لما قتلا\nوبدأت الناس إللي فروا من معركة بدر يعودوا لمكة ويحكوا إللي حصل معاهم في المعركة،\nوصل الخبر لأبو لهب عم رسول الله ﷺ وكان في مكان عند زمزم وكان أبو رافع مولى رسول الله ﷺ في نفس المكان إللي عند زمزم ،\nفبيحكي أبو رافع إللي حصل مع أبو لهب ويقول:\nكنت غلام للعباس، يعني بيساعده في أموره زي العبد كده،\nفأسلمت وأسلمت أم الفضل وأسلم العباس وكان يكتم إسلامه،\nفلما وصل لنا خبر انتصار المسلمين حسينا بعزة وفخر وفرح،\nأما أبو لهب فكان مقهور من إللي حصل،\nفكنت قاعد بنْحت الأقداح في حجرة زمزم وكانت أم الفضل قاعدة معايا واحنا قاعدين فرحانين لنصر المسلمين،\nولقينا أبو لهب جاي علينا بيجر رجله من القهرة وماشي وهو مغموم،\nلحد ما جه وقعد على حَجر وكان ظهره لظهري، يعني أبو لهب قعد في ظهر أبو رافع،\nوهو قاعد سمعنا الناس بتقول : أبو سفيان بن الحارث بن عبد المطلب جاء من الحرب،\n☆أبو سفيان بن الحارث ده غير أبو سفيان بن حرب صاحب القافلة ركزوا\nفنادى عليه أبو لهب وقال له: تعال يابن أخي إنت عندك الخبر الأكيد قل لي إيه إللي حصل \nوالناس حولهم يسمعون ،فقال له أبو سفيان بن الحارث:\nوالله احنا مجرد ما قابلنا المسلمين إلا وكأننا سلمنا نفسنا لهم يقتلوننا ويأسروننا زي ما هم عايزين\nوأنا لا ألومهم على الهزيمة دي، احنا قابلنا رجال بيض على خيول بَلق يعني خيول بيضاء وفيها سواد، بين السماء والأرض والله ما في أحد يقدر عليهم\nفقال أبو رافع: والله دي الملائكة \n☆مقدرش يمسك نفسه من الحماس \nفابو لهب راح رافع إيده وضرب وجه أبو رافع ضربة شديدة فبدأ أبو رافع يعاركه بيدافع عن نفسه،\nلكن أبو رافع كان رجل ضعيف الجسد فراح أبو لهب شايل أبو رافع ورماه في الأرض زي بتوع المصارعة كده وقعد عليه يضرب فيه\nفقامت أم الفضل وجابت عمود وضربت أبو لهب على رأسه فتحت له رأسه فتحة جامدة، وقالت له : \nإنت مستضعفه عشان سيده مش موجود\n☆أبو لهب يبقى أخو زوج أم الفضل واخدين بالكم\nفقام أبو لهب ومشي وهو ذليل، وربنا ابتلاه بداء اسمه العَدَسة، قرحة تتشاءم منها العرب وهي مُعدية، فمعداش سبع ليال إلا ومات أبو لهب،\nوقعد ثلاثة أيام بعد موته أبناؤه خايفين يقربوا منه، فلما خافوا الناس تُعايرهم إنهم تركوا أبوهم من غير دفن،\n حفروا حفرة ودفعوه في الحفرة بعود خشب ورموا عليه الحجارة من بعيد لحد ما غطوه وتركوه ومشيوا\nالمشهد بيقف هنا عند ناس كثير، خلاص الميت اندفن وانتهى الأمر، لكن أبو لهب دي كانت بدايته، بداية العذاب الأبدي:\n\"تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ ۩ مَا أَغْنَى عَنْهُ مَالُهُ وَمَا كَسَبَ۩ سَيَصْلَى نَارًا ذَاتَ لَهَبٍ \"\nيا ترى أبو لهب كان إحساسه عامل إزاي لما شاف ملك الموت وهو جاي يقبض روحه ومعاه ملائكة سود الوجوه معاهم كفن من النار عشان يكفنوا فيه روحه وهم قاعدين قصاده وملك الموت عند رأسه وبيقول :\nأيتها النفس الخبيثة، اخرجي إلى سخط من الله وغضب،\nوروحه تفرقت في جسده خايفة تخرج،\n فانتزعها ملك الموت زي ما بننتزع عود مليان شوك من الصوف المبلول،\nولا لما اتحط في القبر وسمع أصوات أقدام عياله وهم سايبينه وماشيين وواجه بعدها منكر ونكير، الملكان المسؤلان عن امتحان الناس في القبر،\nوإللي وصفهم لوحده يخلينا نطلع نجري لو شفناهم واحنا في الدنيا، مش في قبر مظلم ومفيش منه مفر، \nيا ترى إيه كمية الرعب إللي أبو لهب حس بيها لما شاف ملكان أسودان أزرقان، يحفران الأرض بأنيابهما ،\nأعينهما كالبرق الخاطف وأصواتهما كالرعد القاصف، وبيسألوه: من ربك؟ وما دينك؟ ومن نبيك؟\nوهو بيقول :\nهاه هاه لا أدري ، فينادي مُنادٍ من السماء أفرشوا له من النار وألبسوه من النار وافتحوا له بابا إلى النار \nفجاءه من حرها وسمومها وضاق عليه قبره لحد ما أضلاعه دخلت في بعض، وجاءه رجل قبيح الوجه قبيح الثياب مُنتن الريح ،\nفقال له: أبشر بالذي يسوؤك هذا يومك الذي كنت توعد \nفقال له أبو لهب : من أنت ؟ فوجهك الوجه الذي يجيء بالشر ، فيقول : أنا عملك الخبيث!\nأنا تكذيبك لرسول الله، أنا أذيتك للمسلمين ، أنا كفرك وشركك بالله أنا.....أنا....\nفقال أبو لهب : رب لا تقم الساعة رب لا تقم الساعة!\nومش بس أبو لهب إللي حصل معاه كده، ده أبو جهل وعتبة وأمية وشيبة والنضر وكل كافر وكل فاجر بيحصل معاه كده\nرسول الله ﷺ بعد ما المعركة انتهت أمر الصحابة إنهم يجيبوا جثث أربعة وعشرين رجلا من كبار المشركين إللي قتلوا ويرموها في بئر قديم،\nوبعدها بثلاثة أيام قام رسول الله ﷺ على البئر ينادي المشركين القتلى:\nيا أبا جهل بن هشام، يا عتبة بن ربيعة ، يا شيبة بن ربيعة،\nيا فلان بن فلان....\nأيسُرّكم أنكم أطعتم الله ورسوله؟ يعني تحبوا دلوقتي إنكم كنتم أطعتم الله ورسوله،\nفأنا وجدت ما وعدني ربي حقا\nفهل وجدتم ما وعد ربكم حقا؟!\nفعمر بن الخطاب رضي الله عنه قال له : يا رسول الله!\nإنت بتكلم أجساد مفيهاش أرواح!\nفقال له رسول الله ﷺ:\nوالله هم سامعيني أحسن منكم\nلأن ربنا أحياهم عشان يسمعهم كلام رسول الله ﷺ توبيخا وحسرة عليهم\n☆طبعا السؤال إللي بييجي في بالنا ، هل الميت بيسمع الناس لو كلموه وهو في قبره، وهل يعرف أحوال أهله في الدنيا\nالموضوع فيه تفصيل، الميت لا يسمع أي حاجة من أخبار الدنيا على الإطلاق إلا في مواضع معينة عليها دليل،\nربنا بيقول :\n\"فَإِنَّكَ لَا تُسْمِعُ الْمَوْتَىٰ\" ، \"وَمَا أَنتَ بِمُسْمِعٍ مَّن فِي الْقُبُورِ\"\nالإستثناء بقى زي مثلا في حديث الميت إذا انصرف عنه أهله فإنه يسمع قرع نعالهم، وبيسمع سؤال الملكين في القبر،\nلكن موضوع إن الميت يعرف أخبار أهله في بيوتهم أو يسمعها أو يعرفها حتى، فلا \nكل الأدلة من القرآن والسنة بتقول إن الميت لا يسمع أبدا،\nأما لو حد راح زار ميت يعرفه فلو سلم عليه هل يرد الميت السلام ولّا لأ،\nففيه خلاف، علماء قالوا أه يرد السلام وعلماء تانيين قالوا لأ لضعف الأحاديث إللي ورد فيها الكلام عن رد الميت للسلام.\nفمينفعش بقى لما نروح نزور حد ميت نقعد نشكيله ونحكيله ده أنا حصل لي وحصل لي من بعدك يا فلان\nلأنه أصلا لا يسمع الشكوى دي وكمان ممكن ندخل في الشرك والعياذ بالله من غير ما نحس وده محرم\n◇وطبعا بما إننا بنتكلم عن الميت فمفيش حاجة اسمها أقرأ الفاتحة على روح فلان الكلام ده غير صحيح نهاااائي\nرسول الله ﷺ مات له أبناء وأصحاب وزوجات ومحصلش ولا مرة واحدة إنه قرأ الفاتحة على واحد فيهم والله،\nاحنا بقى جبنا موضوع الفاتحة ده منين\nواحنا متفقين إننا مينفعش نعمل حاجة في الدين رسول الله ﷺ معملهاش عشان عايزين نشرب من الحوض بتاعه إللي اتكلمنا عنه في رحلة الإسراء والمعراج، فاكرين\nإللي بيوصل للميت إننا ندعي له أو نتصدق عنه مثلا نعمل له صدقة جارية وهكذا\n☆والسؤال إللي محير ناس كثير : إزاي ملك الموت يقدر يقبض أكثر من روح في نفس الوقت،\nيعني لو أكثر من واحد جاءت ساعة وفاته إزاي ملك الموت بيقبض أرواحهم كلهم في نفس الوقت\nربنا بيقرب لملك الموت مسافات الأرض حتى تكون بين إيده زي القصعة يعني زي الطبق إللي بيكون بين إيدنا يأخذ من حيث شاء،\nوملك الموت له أعوان بيساعدوه في إخراج الروح من الجسد لحد ما يوصلوها للحلقوم،\nفأول ما توصل الروح للحلقوم يقبضها ملك الموت\nنرجع لهزيمة المشركين في بدر وانتشار خبر نصر المسلمين،\nوصل خبر النصر للنجاشي في الحبشة وفرح جدا لنصر رسول الله ﷺ وأرسل لجعفر بن أبي طالب يبشره بنصر المسلمين على المشركين،\nأرسل رسول الله ﷺ زيد بن حارثة للمدينة عشان يبشرهم بنصر المسلمين وكان يركب على ناقة رسول الله ﷺ وكان اسمها القَصْواء،\nفي الوقت ده كان اليهود نشروا إشاعة في المدينة إن رسول الله ﷺ قُتل،\nومع مجيء زيد بن حارثة قالوا الدليل إن محمد قُتل إن زيد جاي على ناقته، فتجمع الناس حول زيد بن حارثة يسألوه عن الأخبار، \nفقال لهم إن المسلمين انتصروا وإن رسول الله ﷺ بخير،\nوطبعا كانوا مستغربين ، إنتم طالعين لقافلة إزاي حصلت حرب بين المشركين وبينكم \nلكنهم فرحوا جدا بنصر المسلمين، واهتزت المدينة بالتهليل والتكبير،\n في نفس اليوم إللي جاء فيه زيد بن حارثة بالبشرى ماتت رقية بنت رسول الله ﷺ\nوكانت مريضة قبل ما يطلع رسول الله ﷺ في طلب القافلة وأمر زوجها عثمان بن عفان رضي الله عنه إنه يجلس معاها وميخرجش مع رسول الله ﷺ ، \nفخلال الفترة دي المرض اشتد عليها وماتت رضي الله عنها قبل ما رسول الله ﷺ يأتي للمدينة ودفنها عثمان رضي الله عنه،\nتخيلوا لما رسول الله ﷺ يرجع للمدينة ويعرف إن بنته ماتت واندفنت من غير ما يشوفها هتكون مشاعره إيه\n خرج قادات المسلمين إللي كانوا في المدينة إلى طريق بدر عشان يستقبلوا رسول الله ﷺ  ويهنوه بالنصر،\nوفي نفس الوقت كانوا بيعتذروا من رسول الله ﷺ لأنهم لم يشاركوا في أول معركة ضد المشركين،\nوكان من إللي اعتذروا الصحابي أُسيْد بن حضير، فاكرينه\n إللي قال فيه أسعد بن زرارة لمصعب بن عمير اصدق الله في دعوتك له،\nفقال أُسَيد احنا مكناش نعرف يا رسول الله إن هيكون في حرب وكنا مفكرين إنها قافلة زي باقي القوافل ولو كنا نعرف إنك هتحارب مكنش تخلف ولا واحد فينا\nفرسول اللهﷺ قال له : صدقت\nومن الناس إللي حزنت إنها لم تشارك مع رسول الله ﷺ في القتال أنس بن النضر، قال:\nبقى أول قتال لرسول الله ﷺ مع المشركين وأنا محضروش، لو ربنا خلاني أحضر قتال تاني لرسول الله ﷺ ليَرَيَنّ الله ما أصنع\nوصل رسول الله ﷺ للمدينة ومعاه الغنائم ومعاه أسرى بدر،\nطبعا نفسية المسلمين اتغيرت تماما بعد الغزوة دي،\nغزوة بدر كسرت الحاجز النفسي إللي كان عند المسلمين بسبب اضطهادهم وتعذيبهم على مدار سنين،\nخوفهم من إن ممكن حد يهجم عليهم أو حد يبعث يجيبهم من المدينة ويرجعهم مكة تاني خلاص مبقآش موجود،\nالمسلمين حسوا إن خلاص بقى لهم دولة وبقت لهم هيبة بين القبائل العربية،\nوبدأ الناس يسألوا مين هم المسلمين دول وإيه هو الإسلام، فأكيد ده كان فتح من الله من ناحية تانية خالص\nنيجي بقى لتوزيع الغنائم\nبعد ما بدأ المشركون يفروا من أرض المعركة ويتركوا وراءهم الغنائم، يعني الدروع والأحمال إللي كانت على الجمال وهكذا،\nالمسلمون قسموا نفسهم ثلاثة أقسام : \nقسم قعد مع رسول الله ﷺ عشان يحميه،\nوقسم راح وراء الفارّين من أرض المعركة،\nوالقسم الثالث بدأ يجمع الغنائم إللي كانت في أرض المعركة،\nخلصت المعركة والغنائم موجودة ولازم تتوزع،\nبدأ يحصل مشاكل وقلق بين الصحابة\nالناس إللي جمعت الغنائم قالوا : ملكوش فيها نصيب، احنا إللي جمعناها فهي من حقنا كلها\nفالقسم إللي خرج يطارد الفارين من المشركين قالوا :\nلا طبعا احنا كنا بنطارد العدو عشان تعرفوا تلموا الغنائم\nوالقسم الثالث قال:\nطيب احنا كنا مع رسول الله ﷺ بنحميه وانشغلنا به\nوبدأ الخلاف بين الصحابة على توزيع الغنائم\n☆طبعا احنا مستغربين موقف زي ده من الصحابة، إزاي الناس إللي اتحملت الأذى والهجرة وتركت كل أموالها في سبيل الله يقعوا في موقف زي ده\nشوفوا يا جماعة، الصحابة على جلالة قدرهم فهم بشر، بيخطئوا عادي جدا،\nوالعبرة مش بالخطأ، العبرة إن الإنسان لا يستمر على الخطأ\nالصحابة قعدوا ثلاثة عشرة سنة في مكة تحت ظلم وقهر وتعذيب، وحتى بعد الهجرة كانوا عايشين في فقر شديد،\nوأول مرة يشوفوا قصادهم غنائم كثيرة كده،\nفكان طبيعي إنهم يقعوا في خطأ الإلتفات إلى الدنيا، وإن يحصل بينهم خلاف بسبب الدنيا،\nومن حكمة ربنا إن الصحابة يقعوا في خطأ زي ده، عشان احنا كمان نتعلم\nوالخلاف اتحل بمجرد ما نزلت آيات القرآن، نشوف ربنا قال إيه للصحابة:\n\"يَسْأَلُونَكَ عَنِ الْأَنفَالِ ۖ قُلِ الْأَنفَالُ لِلَّهِ وَالرَّسُولِ ۖ فَاتَّقُوا اللَّهَ وَأَصْلِحُوا ذَاتَ بَيْنِكُمْ ۖ وَأَطِيعُوا اللَّهَ وَرَسُولَهُ إِن كُنتُم مُّؤْمِنِينَ \" \nيعني المسلمين بيسألوا عن الغنائم مين يأخذها، قل يا محمد إن الغنائم دي لله يجعلها حيث يشاء، والرسول يقسمها بأمر الله،\nفقسم رسول الله ﷺ الغنائم وجعل أربع أخماس الغنائم للجيش ووزعهم بالتساوي بينهم،\nوطبعا أعطى عثمان بن عفان رضي الله عنه  نصيبه لأنه قعد في المدينة بأمر رسول الله ﷺ  عشان ياخد باله من زوجته رقية، وإلا فهو كان هيخرج مع المسلمين في غزوة بدر،\nأما الخمس الباقي فهو للدولة، من حق رسول الله ﷺ إنه يتصرف فيه كما يريد،\nالأسرى بقى لهم قصة تانية خالص\nرسول الله ﷺ استشار أصحابه يعملوا إيه مع الأسرى،\nفقال أبو بكر الصديق رضي الله عنه :\nيا رسول الله!\nدول أهلنا وعشيرتنا مهما كان ،وأنا شايف إننا نأخذ منهم الفدية، فتكون الأموال إللي هناخدها منهم قوة لنا،\nكمان لما نخليهم يمكن ربنا يهديهم ويدخلوا الإسلام ويكونوا عون لنا، لكن لو ماتوا هيموتوا على الكفر!\n☆لو فكرنا هنلاقي إن رأي أبو بكر الصديق مناسب فعلا ، والمسلمين هيستفيدوا أكيد، وحتى ده من رحمة الإسلام\nوكان رأي أبو بكر الصديق مشابه لرأي رسول الله ﷺ في أوقات كثيرة،\nوطبيعته كانت قريبة جدا من طبيعة رسول الله ﷺ، وكان يغلب عليه طابع الرحمة، لدرجة إن رسول الله ﷺ كان يقول عن أبي بكر :\nأرحم أمتي بأمتي أبو بكر\nسأل رسول الله ﷺ عمر بن الخطاب، عشان يشوف هل في رأي أحسن أو في وجهة نظر تانية،\nفقال عمر :\nلا يا رسول الله، أنا رأيي مختلف عن رأي أبي بكر\nأنا رأيي إنك تعطي كل أسير من المشركين لقريبه من المسلمين فيقتله، خلي حمزة ياخد أخوه ويقتله،\nوخلي علي ياخد أخوه عقيل ويقتله، فدول صناديد الكفر، عشان ربنا يعلم إن مفيش في قلوبنا رحمة ولا أي حب للمشركين حتى ولو كانوا أقرب الناس لهم\n☆عارفين عمر بن الخطاب رضي الله عنه لو كان في زماننا وقال الرأي ده الناس كانت عملت فيه إيه\nوالله كان زمانهم مش بس قالوا عنه إرهابي وإنه معندوش قلب ، ده كان زمانهم رموه بالحجارة\nرسول الله ﷺ لما سمع قول عمر بن الخطاب سكت وأحب قول أبو بكر الصديق أكثر،\nوقال للناس اقبلوا منهم الفداء، وإللي مكنش معاه أموال يفدي بها نفسه، جعله رسول الله ﷺ يعلم أبناء المسلمين القراءة والكتابة،\nدخل عمر بن الخطاب على رسول الله ﷺ وكان معاه أبو بكر الصديق رضي الله عنه فلقاهم قاعدين يبكوا،\nفسألهما: ليه بتبكوا\nفقال له رسول الله ﷺ: أنا اتعرض علي عذاب أصحابك وكان أقرب من الشجرة إللي هناك دي،\nولو حد فيهم نجا من العذاب هتكون إنت يابن الخطاب\nنزل القرآن بيؤيد رأيك قال الله عز وجل :\n\"مَا كَانَ لِنَبِيٍّ أَنْ يَكُونَ لَهُ أَسْرَى حَتَّى يُثْخِنَ فِي الأَرْضِ تُرِيدُونَ عَرَضَ الدُّنْيَا وَاللَّهُ يُرِيدُ الآخِرَةَ وَاللَّهُ عَزِيزٌ حَكِيمٌ\"\nالقرآن نزل يلوم ويعتب على رسول الله ﷺ إنه لم يقتل هؤلاء الأسرى،\nومش معنى كده إن ديننا دين متعطش للدماء\nربنا بيضع لنا قاعدة إن صناديد قريش أو خلونا نقول بلغة عصرنا مجرمي الحرب دول يقتلوا\nوالأدلة في الإسلام توصي بالإحسان للأسرى بصفة عامة ومعاملتهم معاملة رحيمة،\nأما بقى إللي واخدين الحروب كتجارة وإللي بيحاربوا دين ربنا ليل نهار دول لازم يقتلوا، مينفعش التعامل معاهم\nكأسرى حرب،\nيعني واحد زي بشار الأسد ده، هل لو حد أسره يعمل له محاكمة ولا يُقتل في نفس اللحظة إللي يُأسر فيها، لقتله وحرقه للنساء و الأطفال ومحاربته لدين الله؟\nده غلب النّضر بن الحارث \nفربنا لام على المسلمين قبولهم الفداء ولكنه عفا عنهم في الآخر،\nوكانت دي أول مرة يوافق حكم عمر بن الخطاب حكم ربنا من فوق سبع سماوات\nكان من أسرى المشركين أبو العاص بن الربيع زوج زينب بنت رسول الله ﷺ،\nيا ترى هل المسلمين هيطلقوه بدون فداء ولا هيتعاملوا معاه زي باقي الأسرى،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 89, "l": "الجزء 63 | احداث السنه الثانيه من الهجره | زينب بنت رسول الله", "u": "https://www.facebook.com/groups/710210019782034/permalink/795316321271403/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثالثة_والستون\n#أحداث_السنة_الثانية_من_الهجرة\n#زينب_بنت_رسول_الله\nقبل ما نبدأ حلقة النهاردة حاب أوضح حاجة\nوهي إن الهدف الرئيسي من سلسة السيرة إللي أنا بشرحها دي إننا نعيش الأحداث بالتفصيل مع رسول الله ﷺ والصحابة من المهاجرين والأنصار وبالتالي نحبهم لأن حبهم من الإيمان\nرسول الله ﷺ قال : \n\" لا يؤمن أحدكم حتى أكون أحب إليه من والده وولده والناس أجمعين.\"\nوقال عن الأنصار : \"لا يُحِبُّهُمْ إِلاَّ مُؤمِنٌ، وَلا يُبْغِضُهُمْ إِلاَّ مُنَافِقٌ، مَنْ أَحَبَّهُمْ أحبَّه اللَّهُ، وَمَنْ أَبْغَضَهُمْ أَبْغَضَهُ اللَّه\"\nأما الهدف الثاني فهو إني عايزاكم تطلعوا من السيرة\n《بأكبر كمية معلومات أساسية صحيحة عن دين الإسلام》\nيعني أنا مش مجرد بحكي قصة رسول الله ﷺ، لأ أنا بشرح لكم الإسلام من خلال سيرة رسول الله ﷺ، \nوانتم أكيد لاحظتم ده من خلال الستين جزء إللي فاتوا\nفمتستغربوش لما تلاقوني بتكلم عن حكم شرعي معين زي حكم حلق اللحية أو حكم البدعة أو حكم من يسب رسول الله ﷺ  إللي اتكلمنا عنهم قبل كده،\nأو تلاقوني بتكلم عن كيفية موت الكافر زي المرة إللي فاتت لما اتكلمنا عن موت أبي لهب وكفار قريش،\nأو تلاقوني اتكلمت عن علامات الساعة، لأن كل دي من السيرة،\nلأن الكلام ده كله موجود في أحاديث رسول الله ﷺ وهو قالها للصحابة، يبقى تبع السيرة ولّا لأ\nفأنا ناوية إن شاء الله إن السلسلة دي تكون شاملة على الأقل المعلومات المهمة إللي مينفعش نكون مسلمين ومش عارفينها، وعشان نقدر نجاوب على أسئلة منكر ونكير في القبر : من ربك؟ ما دينك؟ من نبيك؟ \nعشان كده أنا مش بجيب غير الأحاديث الصحيحة فقط، ولو في حديث مختلف في صحته في الغالب مش بجيبه أو لو قلته بقول لكم عنه إنه مختلف في صحته،\nفأنا مش عايزاكم تزهقوا لما تلاقوا إننا قعدنا في حَدث واحد كذا حلقة، وانتم أكيد استفدتم إن شاء الله\nفاحتسبوا نية إنكم بتتعلموا علم شرعي: \nفقه وعقيدة وتفسير وأخلاق وحديث وتاريخ، كل ده موجود في السيرة \nطولت عليكم\nندخل بقى في حلقة النهاردة بقى \nاتكلمنا المرة إللي فاتت عن التعامل مع الأسرى ومع توزيع الغنائم ووقفنا عند الأسير أبو العاص بن الربيع زوج زينب بنت رسول الله ﷺ وإزاي الصحابة هيتعاملوا معاه،\nأبو العاص بن الربيع كان متزوج من زينب وهي أكبر بنات رسول الله ﷺ من قبل البعثة النبوية، وهو ابن خالتها هالة بنت خويلد،\nفلما بُعث رسول الله ﷺ كفار قريش طلبوا منه إنه يطلق زوجته زينب زي ما أبو لهب أمر ابنيه أن يطلقا ابنتي رسول الله ﷺ رقية وأم كلثوم إللي اتكلمنا عنهم في البداية،\nلكن أبو العاص بن الربيع رفض إنه يعمل كده،\nوكان يُحسن للسيدة زينب ويكرمها وكان يحبها وكان رجل أمين، وأسلمت زينب وعرضت على زوجها الإسلام ولكنه رفض، وعاش معاها أكثر من خمسة عشر عاما،\nوكان في بداية الإسلام عادي إن المرأة المسلمة تعيش مع زوجها الكافر، ونزل التحريم بعدين زي ما هنشوف إن شاء الله\nخرج أبو العاص بن الربيع مع المشركين في بدر لقتال رسول الله ﷺ وكان من الأسرى، فلما رسول الله ﷺ قال بالفداء،\nيعني كل واحد يفدي قريبه بالمال،\nبعثت زينب رضي الله عنها مع أخو زوجها لرسول الله ﷺ قلادة لها كانت أمها خديجة أهدتها لها لما تزوجت،\nفلما رأى رسول الله ﷺ القلادة رقّ قلبه جدا وتذكر خديجة رضي الله عنها وقال للمسلمين:\nلو حابين تطلقوا لها أسيرها فافعلوا\nفأطلقوا أبو العاص بن الربيع بدون فداء فوعد أبو العاص رسول الله ﷺ إنه يرسل له زينب، ورجعوا القلادة لزينب رضي الله عنها،\nوأوْفى أبو العاص بن الربيع بوعده لرسول اللهﷺ وأرسل له زينب مع إنه كان بيحبها جدا،\nوكان ممكن يقول خلاص بقى أنا في مكة ودي زوجتي وعندي والمسلمين مش هيقدروا يمسكوني،\nالعرب كان عندهم الوفاء بالعهد ده حاجة كبيرة أوي\nبعث رسول الله ﷺ زيد بن حارثة ومعاه رجل من الأنصار  لمكان قريب من مكة عشان لما يشوفوا زينب يأخذوها ويأتوا بها لرسول الله ﷺ، وزيد بن حارثة في الوقت ده كان اسمه زيد بن محمد يعني يعتبر أخو زينب،\nفتقابل زيد مع زينب وأخذها ورجع بها للمدينة مع طفليها علي وأُمامة،\nوقعدت في المدينة مع رسول الله ﷺ لحد قبل فتح مكة\nوكان رسول الله ﷺ بيرعى أبناء زينب رضي الله عنها علي وأُمامة،\nوكان رسول الله ﷺ بيشيل أُمامة على كتفه وهو بيصلي،\nيعني كان لما يبقى واقف يصلي يفضل شايلها ولما كان يسجد كان يضعها في الأرض ولما يقوم يشيلها تاني\n☆وهنا في نقطة بالنسبة للنساء إللي عندها أطفال صغيرين وبتواجه مشكلة في الصلاة،\nرسول الله ﷺ بطريقة عملية بيقول لنا إن إللي عنده طفل يقدر يشيله ويحطه في الصلاة عادي ودي حاجة لا تبطل الصلاة،\nونقطة كمان بمناسبة إن النساء بتروح تصلي التروايح في رمضان وبتاخد عيالها معاها،\nرسول الله ﷺ كان بياخد أمامة معاه المسجد، وكانت صغيرة فده معناه إنه يجوز للأطفال الذهاب للمسجد،\nفبراحة على النساء إللي بييجوا المسجد مع أطفالهم\nوبالنسبة للنساء إللي بياخدوا أطفالهم معاهم،\nإنتم جايين عشان تاخدوا ثواب صح\nقبل ما تنزلوا من البيت علموا عيالكم أداب المسجد، وفهموهم إن المسجد ده مش للعب وهاتوا لهم مثلا كتب تلوين وألوان يقعدوا يلونوا فيها،\nوأنا شفت أم جايبة لبنتها ألوان وورق مطبوع وأطفال المسجد حوالين البنت وكلهم قاعدين في جنب بيلونوا مع بعض ومبسوطين،\nالأطفال بيحسوا بملل عشان كده بيعملوا دوشة لكن لو احنا راعيناهم وشغلناهم مش هيبقى في مشكلة خالص،\nلو ابنك سنه لسه صغير أوي يبقى دوا المغص معاكي يا حبيبتي وأي لعبة كده صغيرة معاه، وإزازة مية صغيرة تشربيه منها كل شوية عشان المية بتهدي الأطفال،\nعيط ومفيش حاجة جايبة نتيجة وعايزك تشيليه، خلاص شيليه واعملي زي رسول الله ﷺ،\nالأمور بسيطة والله يا جماعة بس احنا إللي بنعقدها، يعني الناس إللي بتقعد تزعق للأطفال في المساجد لو عملوا دوشة في صلاة التروايح إللي هي سنة بحجة إنهم مش عارفين يركزوا؛\n هم هم إللي بيصلوا الظهر والعصر وباقي الصلوات إللي هي فرض ودماغهم مشغولة بهعمل أكل إيه وأرتب كذا إزاي ومشغولين بهموم الدنيا كلها\nعروة بن الزبير بن العوام رجله جاء فيها مرض وكان لازم تتقطع فقالوا له يشرب خمر عشان ميحسش بالألم فقال لهم اقطعوها لي وأنا بصلي وأنا مش هحس بحاجة،\nوفعلا قطعوها له وهو بيصلي، \nفاللي عايز يصلي بخشوع هيصلي بغض النظر حواليه إيه\nفالله يكرمكم بلاش نخلي الأطفال يكرهوا المساجد بسبب تعاملنا معاهم،\nالأطفال مش بينسوا المواقف دي أبدا، وأنا منهم \nلما كنت صغيرة واحدة زعقت لي في المسجد عشان بس ضحكت وكنت بتكلم بصوت واطي جدا ومن ساعتها وأنا منستش الموقف ده وبقيت كل ما أشوفها مفتكرش منها غير موقفها ده معايا،\nوالإمام أصلا كان بيصلي وصوته عالي في الميكروفون،\nفاللي هو انتِ سمعتي صوت ضحكة طفلة صغيرة وسايبة صوت الإمام العالي،\nيبقى المشكلة في مين بالضبط هنا، رفقا بالأطفال...رفقا بالأطفال\nنرجع لقصة أبو العاص مع زوجته زينب عشان نبقى خلصناها ومنرجعلهاش تاني\n أبو العاص خرج للتجارة في الشام في سنة ست للهجرة وكان معاه أموال قريش، وقابلته سرّية من سرايا المسلمين فأخذت أمواله وهو عرف يهرب وراح المدينة ووصل لزينب رضي الله عنها وطلب منها إنها تحميه،\nفقالت من باب حجرتها : أيها الناس أنا زينب بنت محمد ﷺ قد أجرت ابا العاصِ بن الربيع، يعني أبو العاص في حمايتي،\nوساعتها كان رسول الله ﷺ كبّر لصلاة الصبح،\nفلما خلص صلاة قال للصحابة : سمعتم إللي أنا سمعته؟!\nوالله أنا ما عرفت حاجة عن الموضوع، أنا زيي زيكم أول مرة أسمع الكلام ده، وإنه ليجير على المسلمين أدناهم،\nيعني أي واحد من المسلمين مهما كان يقول إنه حمى حد معين يبقى لازم نقبل بحمايته دي\nوانصرف رسول الله ﷺ ورجع لبنته وقال لها :\nأحسني لأبا العاص، ولكن ميقربش منك فهو لا يحل لك!\nوقال رسول الله ﷺ للمسلمين: \nانتم عارفين أبو العاص بن الربيع يقرب لنا إيه ومنزلته إيه عندنا، فلو حابين تحسنوا له وتردوا عليه الأموال بتاعته فاحنا نحب كده،\nولو مش عايزين خلاص، دي حاجة ربنا رزقكم بها وهي حلال لكم\nفقال الصحابة :بل نرد عليه أمواله يا رسول الله،\nوردوا عليه كل إللي كان في القافلة ورجع أبو العاص بن الربيع لمكة وأعطى الناس كلها حقوقها وسألهم: \nيا معشر قريش هل في أحد فيكم باقي له شيء عندي، كل واحد أخذ حقه؟\nفقالوا : جزاك الله خيرا، انت كنت عفيف كريم معانا\nفقال لهم : أشهد ألا إله إلا الله وأن محمدا رسول الله\nأنا مرضيتش أسلم عنده عشان متقولوش إني هاكل عليكم أموالكم ، لكن بما إني رديت لكل واحد حقه فخلاص أسلمت\nوخرج أبو العاص ورجع لرسول الله ﷺ مهاجرا ورد رسول الله ﷺ عليه زوجته زينب رضي الله عنها،\nوعاش معها سنة واحدة ثم ماتت في السنة الثامنة من الهجرة، ومات زوجها بعدها بأربع سنوات سنة اثنا عشرة للهجرة.\nعملية فداء الأسرى استمرت لحد ما أُطلق سراح الأسرى،\nوأسلم بعض الأسرى بعدين، زي الوليد بن الوليد بن المغيرة أخو خالد بن الوليد، وأسلم أبو عزيز أخو مصعب بن عمير،\nوحصلت حادثة بمناسبة موضوع الأسرى ده\nواحد من المشركين اسمه عُمير بن وهب كان قاعد عند الكعبة مع صفوان بن أمية بن خلف إللي قتله بلال وأصحابه وكان من المشركين هو كمان،\nفكان بيتكلم عن إللي حصل للمشركين في بدر فقال صفوان:\nوالله مفيش خير في الحياة بعدهم\nفقال له عمير بن وهب:\nمعاك حق والله، ولولا إن أنا عليّ ديْن وعندي عيال أخاف عليهم يضيعوا من بعدي لو مت لكنت روحت قتلت محمد فأنا عندي سبب إني أروح المدينة لان ابني أسير هناك\nصفوان مصدق أخذ الكلمة منه، فقال له :\nدينك ديني انا هدفعه بدالك وعيالك عيالي متخافش عليهم روح اقتله\nفقال له عمير : خلاص خلي الموضوع ده سر بيننا\nفصفوان قال له : ماشي اتفقنا\nفأمر عمير بسيفه إنه يُحد عشان يبقى حامي، زي ما بنحمي السكاكين كده \nوأمر إنه يتحط فيه سم، وأخذ سيفه وانطلق ناحية المدينة، \nلما وصل على باب المسجد ومعاه سيفه، \nكان عمر بن الخطاب رضي الله عنه واقف مع مجموعة من المسلمين بيتكلموا عن إللي حصل في بدر وعن هلاك عدوهم، وعن نصر ربنا لهم،\nفرأى عمير بن وهب فقال للي كانوا معاه:\nعمير بن وهب ده لم يأتِ إلا لشر، هو إللي كان بيحرش بيننا وبين الناس في بدر عشان نقاتل بعض، وهو إللي خمن عددنا كان كام في بدر،\nدخل عمر على رسول الله ﷺ وقال له: يارسول الله! عمير بن وهب جاي وهو شايل سيفه معاه\nوهو خارج من عند رسول الله ﷺ لقى علي بن أبي طالب مدخله على رسول الله ﷺ ، فراح ماسكه من حمالة السيف من عند رقبته كأنه ماسك في خناقه\nوقال للأنصار إللي كانوا معاه ادخلوا على رسول الله ﷺ وخليكم عنده، أنا لا أأمن عليه من الرجل الخبيث ده\nفلما دخلوا على رسول الله ﷺ ورأى عمر وهو ماسك عمير بن وهب قال له :\nسيبه ياعمر...قرب مني يا عمير!\nفقال عمير بن وهب:\nأنعموا صباحا! يعني بلغتنا صباح الخير\nفقال له رسول الله ﷺ وخدوا بالكم من الكلام:\nربنا أنعم علينا بتحية أحسن من تحيتك وهي السلام تحية أهل الجنة\n☆عشان الناس إللي بيسيبوا تحية الإسلام تحية أهل الجنة ويقولوا صباح الخير و...و...\nرسول الله ﷺ بيقول لكم أهه إن تحية الإسلام أفضل من أي تحية تانية\nفقال عمير لرسول الله ﷺ:\nوالله يامحمد أنا لسه عارف الموضوع، مكنتش أعرف قبل كده\nفقال له رسول الله ﷺ:\nإيه إللي جابك المدينة يا عمير ؟\nفقال عمير : جيت أفتدي الأسير إللي عندكم، فأحسنوا فيه\nفقال له رسول الله ﷺ: طيب والسيف إللي إنت شايله ده شايله ليه؟\nفقال له عمير : وهي يعني السيوف كانت نفعتنا بحاجة \nفقال له رسول الله ﷺ: قول الحقيقة يا عمير، إنت جاي ليه\nفقال له عمير : أنا مجتش إلا لكده\nفقال له رسول الله ﷺ: \nبل قعدت مع صفوان عند الكعبة فافتكرتم زعماء مكة إللي قُتلوا في بدر، وبعدين قلت لصفوان لولا دين علي وعيال عندي لخرجت حتى أقتل محمداً، \nفتحمّل صفوان عنك الدين والعيال على إنك تيجي وتقتلني، وأنا بقولك إن ربنا حائل بيني وبينك، يعني ربنا هيحميني منك\nفقال عمير:\nأشهد أنك رسول الله \nوالله ما في حد حضر الكلام ده ولا عرف به غيري أنا وصفوان \nفالحمد لله إللي جعلني آجي هنا وهداني للإسلام\nوشهد عمير شهادة الإسلام وقال رسول الله ﷺ: أطلقوا له أسيره وعلموه أمور دينه\nفاستأذن عمير رسول الله ﷺ إنه يرجع لمكة ويدعو الناس هناك لعل ربنا يهديهم، فأَذن له رسول الله ﷺ، \nفي الوقت إللي عمير سافر فيه عشان ينفذ عملية الإغتيال دي، كان صفوان عمال يقول لأهل مكة: \nأبشروا! هتحصل حاجة حلوة خلال أيام تنسيكم إللي حصل في بدر\nفكان كل شوية يسأل عنه الرّكبَان إللي في القوافل، ففي يوم سأل عنه راكب فقال له إن أسلم\nأنا عايزاكم تتخيلوا صدمة صفوان وقهرته لما سمع إن عمير أسلم\nطبعا غضب واتضايق، وحلف إنه مش هيكلمه تاني أبدا ولا هيساعده في أي حاجة أبدا\n☆قصة صفوان مع عمير إسنادها حسن وفي بعض العلماء قالوا ضعيفة، ولكن دي القصة الوحيدة المشهورة في إسلام عمير بن وهب عشان كده قلتها \nحصلت أحداث بعد غزوة بدر في المدينة،\nمن أهم الأحداث إللي حصلت ظهور طائفة جديدة في المدينة وهيكون لها أثر سيء كبير جدا في أحداث هتحصل بعدين، الطائفة دي اسمها طائفة المنافقين\n☆المنافق هو إللي بيظهر الإسلام ويُخفي الكفر في قلبه،\nوالمنافق ده مش بيظهر إلا لما تكون دولة الإسلام قوية،\nلأن بيبقى خايف على نفسه وعلى مصالحه،\nلكن لو دولة الإسلام ضعيفة والمسلمين مضطهدين مفيش داعي للنفاق،\nومثال على كده في السنوات الأخيرة كان في طائفة معينة الناس كلها كانت معاها وبتؤيدها،\nوأول ما وقعت الناس إللي كانوا بيؤيدوهم انقلبوا ضدهم وبقوا يشتموا فيهم ويحرضوا عليهم، \nودي سنة كونية\nطول ما الإنسان قوي هتلاقي ناس كتير واقفة جنبه ومعاه وأول ما يقع، مش هيلاقي جنبه غير الصادقين ده إذا لقى حد أصلا،\nوهتلاقوا ده موجود في حياتنا اليومية بصفة عامة\nمن بقى كان زعيم المنافقين دوووول\nعبد الله بن أُبي بن سلول، بعد ما كان زعيم المشركين بقى زعيم المنافقين\nوطبعا موضوع المنافقين ده عايز له شرح فهخليه الجزء الجاي إن شاء الله\nفي رمضان بعد غزوة بدر فُرضت زكاة الفطر، \nوزكاة الفطر دي بكل بساطة:\n◇طعام بنطلعه قبل صلاة العيد أو ممكن قبلها بيوم أو يومين، لكن مش بعد صلاة العيد إطلاقا\n◇والطعام ده بيكون على حسب طعام أهل البلد يعني ممكن أرز أو قمح أو أي حبوب،\n◇والكمية إللي بنطلعها حوالي من اثنين كيلو ونص إلى ثلاثة كيلو جرام على اختلاف وزن الحبوب.\n◇بنعطيها للفقراء والمساكين واحنا عرّفناهم قبل كده\nوهما عالسريع كده :\nالمسكين هو إللي يملك شيء ولكنه لسه محتاج، عنده أموال مثلا لكن مش مكفياه، أما الفقير فهو إللي معندهوش أي شيء إطلاقا.\n◇وبنطلع زكاة الفطر دي عن الكبير والصغير والذكر والأنثى والحر والعبد،\nأما لو امرأة حامل فلا يجب على جنينها زكاة، لكن مستحب.\n◇وزكاة الفطر يجب إخراجها طعام، مينفعش نطلعها مال\nلو متعرفش حد تعطي له زكاة الفطر أو متعرفش تروح تشتري وتوزع،\nممكن تعطوا فلوس الزكاة لمسجد بيجمع فلوس زكاة الفطر ويشتري بها حبوب ويوزع الحبوب دي على الفقراء،\nلكن لازم تكون متأكد إنهم بيطلعوها حبوب لأن مينفعش إخراجها مال، وده كمان رأي الجمهور المالكية والشافعية والحنابلة\nإلا لو حصل اضطرار، زي مثلا واحد على ظهر سفينة ليلة العيد ومش هيعرف يشتري حبوب ويجب عليه إخراج زكاة الفطر، فيجوز إخراجها ساعتها نقود لأي فقير أو مسكين\n☆طيب ليه منطلعهاش نقود، يعني الفقير عنده رز والعدس والحاجات دي، ومحتاج فلوس، يبقى الفلوس أولى\n◇أولا:\n زكاة الفطر دي عبادة والعبادات توقيفية، يعني زي ما ربنا قال عليها...ننفذها بالضبط،\nزي ما بنصلي كده، ينفع واحد ييجي يقول نخلي الفاتحة في الركوع، أو نخلي السجود الأول وبعدين الركوع؟\nطبعا لأ\nلأن رسول الله ﷺ قال: صلوا كما رأيتموني أصلي،\nكذلك زكاة الفطر نطلعها زي ما رسول الله ﷺ طلعها هو والصحابة حبوب\n◇ثانيا: \nزكاة الفطر عن الشخص الواحد حاجة يسيرة يعني كيلو الرز مثلا قولوا بخمسة عشرة جنيهات مصري،\nلو أسرة فيها ستة أشخاص يبقى الزكاة بتاعتهم مائتين خمسة وعشرين جنيه،\nدول ممكن يجيبوا إيه لفرد واحد في أسرة فقيرة\nإللي يفرق هي زكاة المال، الشخص بيطلع فيها مبلغ كبير\nشوفتم السيرة حلوة إزاي بتعلمنا الدين \nإن شاء الله المرة الجاية نكمل باقي أحداث السنة الثانية من الهجرة، ونتكلم بالتفصيل عن المنافقين\n☆"}, {"n": 90, "l": "الجزء 64 | تابع احداث السنه الثانيه من الهجره | المنافقين صفاتهم والتعامل معهم | يهود بني قينقاع", "u": "https://www.facebook.com/groups/710210019782034/permalink/796814217788280/", "t": "امتا تقول ع الي قصادك دا منافق ولا لا عشان متكونش حملت لنفسك كبيره من الكبائر \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الرابعة_والستون\n#تابع_أحداث_السنة_الثانية_من_الهجرة\n#المنافقين_صفاتهم_والتعامل_معهم\n#يهود_بني_قينقاع\nاتكلمنا المرة إللي فاتت عن ظهور طائفة جديدة من الناس في المدينة وهي طائفة المنافقين،\nوقلنا إن المنافق هو إللي بيُظهر الإيمان ويُبطن الكفر عشان خايف على نفسه أو خايف على مصالحه،\nوالطائفة دي مش بتظهر إلا لما يكون الإسلام أو دولة الإسلام قوية،\nوكان زعيم طائفة المنافقين دي واحد اسمه عبد الله بن أُبي بن سلول، إللي كان بيكره رسول الله ﷺ جدا،\nماهو إللي أخذ منه ملك المدينة\nوهنشوف خلال السيرة إنه مكنش بيفوّت أي فرصة ممكن يؤذي فيها رسول الله ﷺ، أو يُشعل الفتنة بين المسلمين إلا ويستغلها\nلكن العجيب إن رسول الله ﷺ على الرغم من الأذى إللي شافه من المنافقين خلال حياته، مكنش بيفكر يقتلهم،\n كان سياسة رسول الله ﷺ مع المنافقين إنه يتغاضى عن مصائبهم وأخطائهم سواء كانت كبيرة أو صغيرة خصوصا في بداية الإسلام،\nليه طيب مع إنهم كانوا بيطعنوا في الدين وبيتعاملوا مع أعداء الإسلام لهدم الإسلام \n◇أولا :\nرسول الله ﷺ كان دائما يتألّف قلوبهم بالإحسان لهم، لعلهم يتوبوا ويرجعوا عن نفاقهم ده.\n◇ثانيا: \nالمنافقين كان لهم في قومهم نوع من السيادة، فلما رسول الله ﷺ يعفو عنهم هو كده بيؤلف قلوب أقوامهم، بعكس لو أخذهم وقتلهم،\nممكن المسلمين صادقي الإيمان يثوروا حَميّة للناس دي وخصوصا إننا لسه قريبي عهد بالجاهلية والعصبية لسه آثارها موجودة ولو كانت بسيطة\n◇ثالثا:\nانتم عارفين لما يحصل حَدث والناس بتنقله بينهم، وكل واحد بينقل بطريقته وساعات يزود كلمة أو ينقص كلمة على ما يوصل لآخر واحد بيكون الموضوع اتغير خالص\nفرسول الله ﷺ كان فاهم النقطة دي كويس جدا،\nوالمشركين والمنافقين ما هيصدقوا إن رسول الله ﷺ يقتل واحد ظاهره الإسلام عشان يشوهوا صورة رسول الله ﷺ وصورة الإسلام،\nوالناس بصفة عامة بتسمع عن من يُقتل، لكن ميعرفوش سبب القتل،وهو ممكن يكون مجرم ويستاهل القتل ألف مرة،\nلكن يوصلوا للناس إنه مسكين وإنه اتقتل غدر بقى ويعملوا عليه فيلم\nفكان لما أي واحد من أصحاب رسول الله ﷺ  يقول له يقتل أي واحد ظهر منه نفاق كان يقول :\nلا، عشان محدش يقول إن محمد بيقتل أصحابه\n◇رابعا:\nالأصل في الشرع إن مجرد ما أي إنسان يُظهر الإسلام، يعني يقول أشهد أن لا إله إلا الله وأن محمدا رسول الله يبقى ينطبق عليه كل أحكام الإسلام ومنها عصمة دمه،\nيعني محدش يقدر يقتله\nأما إللي في قلبه ربنا يحاسبه عليه يوم القيامة ملناش دعوة بيه\nوشوفوا موقف رسول الله ﷺ مع رجل اعترض على قسمته للمال، وقال له : يا رسول الله اتق الله، فواحد من الصحابة قال له: يا رسول الله، خليني اقطع رأسه \nفقال له رسول الله ﷺ: سيبه يمكن بيصلي!\nفقال له الصحابي: \nكم واحد بيصلي يقول بلسانه ما ليس في قلبه!\n☆والجملة دي بنسمعها كتير أوي من الناس\nرد رسول الله ﷺ وقال:\nإني لم أُومَر أن أَنْقب عن قلوب الناس ولا أشُقّ بطونهم\nيعني أنا مليش إلا الظاهر، ربنا لم يأمرني بإني أفتح قلوب الناس وأشوف فيها إيه.\n◇خامسا:\nمينفعش الحكم بالقتل على إنسان إلا ببينة أو بشهادة الشهود أمام الناس حتى لو كان رسول الله ﷺ يعرفهم بالوحي، \nلأن لازم الدليل قصاد الناس، وخصوصا إن المنافقين لما كانوا بيعملوا حاجة تظهر كفرهم الداخلي سواء بالكلام أو الأفعال وكان رسول الله ﷺ يواجههم، زي ما ربنا قال عنهم:\n\"وَلَتَعْرِفَنَّهُمْ فِي لَحْنِ الْقَوْلِ\"\nكانوا على طول يقولوا والله ما قلنا، والله ما عملنا، \nفكانوا بيقعدوا يحلفوا ويظهروا إسلامهم وإيمانهم عشان رسول الله ﷺ لا يقتلهم\n☆ممكن هنا حد يسأل، طيب معنى كده إن المسلمين لما كانوا في مكة كانوا بيمارسوا دور النفاق العكسي، \nيعني يُبطنوا الإيمان ويظهروا الكفر \nمحدش من المسلمين إللي كانوا بيكتموا إيمانهم كان بيشارك المشركين في عبادتهم، ولا يُقيم شعائرهم،\nبالعكس كانوا على طول مع رسول الله ﷺ بيتعلموا منه العلم، بعكس المنافقين في المدينة كانوا بيروحوا يصلوا مع المسلمين وبيحضروا صلاة الجمعة\n☆طيب هل ممكن إننا نعرف المنافقين دول في حياتنا ونقدر نميزهم\nالمنافقين لهم صفات معينة ربنا ذكرها في القرآن ورسول الله ﷺ ذكرها في الأحاديث الصحيحة لو اجتمعت في إنسان 《بصفة دائمة》يبقى هو منافق والصفات دي سريعا هي:\nالتخلف عن الصلاة وخصوصا الفجر والعشاء/ عدم ذكر الله أو ذكره قليلا جدا/ الكذب/إخلاف الوعد/الفُجر في الخصومة،\n يعني لو واحدة زعلت من واحدة تلاقيها بتشتمها وتبهدلها وتفشي أسرارها وممكن تتهمها بحاجات مش فيها/\nخيانة الأمانة/الغدر/لما نيجي ندعوهم يعرضوا عن دين ربنا/شوية تلاقيهم بيناصروا المؤمنين وشوية يناصروا أعداءهم، على حسب الغَلبة مع مين/الاستهزاء بالله ورسوله/\nالأمر بالمنكر والنهي عن المعروف/الاهتمام بالمظهر مع فساد قلوبهم وعدم اهتمامهم بها.\n☆طيب لو واحد فيه بعض الصفات دي يبقى كده منافق\nلأ، يبقى فيه صفة من صفات المنافقين لحد ما يتركها\n☆السؤال المهم بقى، هل يجوز إننا نقول على حد بعينه إنه منافق \nلو المقصود بإني أقول على فلان ده منافق النفاق إللي هو بيُظهر الإيمان بالله وملائكته وكتبه ورسله ويُبطن الكفر بالله، يبقى لا يجوز \nلأن محدش يعرف إللي في القلب غير ربنا، وده اسمه نفاق أكبر، ولازم له وحي من عند ربنا عشان نعرف إن فلان ده منافق نفاق أكبر، والمنافق نفاق أكبر مُخلّد في النار\nأما النفاق الأصغر فهو النفاق العملي، وإللي لسه قايلين صفاته \n فيجوز إننا نقول على من أظهر الصفات دي\n 《بصفة دائمة》 إنه منافق، زي ما بنوصف العاصي بالفسق والعصيان،\nلكن مش واحد مثلا شفناه مش بيذكر ربنا كثيرا فنقول عليه منافق، احنا نشوف باقي الصفات،\nفلو مش بيذكر ربنا كثيرا لكن محافظ على الصلوات ومجتهد فيها ميبقآش منافق،\nلو واحد حصل منه ووقع في كذبة أو أخلف وعده مرة،\nميبقآش منافق، لكن إللي اجتمعت فيه صفات المنافقين بصفة دااااائمة هو ده المنافق،\nعشان بس الناس إللي بتقعد تتهم مشايخ معينة بالنفاق لمجرد إن حصل منهم مواقف معينة مش على هواهم، أو شايفين إن مكنش المفروض يعملوا كده،\nوهم مش عارفين أي حاجة خالص، وخصوصا لو كانوا طول عمرهم ناس أفاضل، ومظهرش منهم إلا كل خير،\nفقبل ما نقول على فلان إنه منافق،\nلازم نشوف هل فيه صفات المنافقين إللي ربنا ورسوله قالوا عليها ولّا لأ؟\nوعشان نعرف نحكم لازم نكون معاشرين الشخص ده،\nطيب لو مش معاشرينه وعارفينه معرفة سطحية من بعييييد ، ومنعرفش عنه حاجة ولا عمرنا قابلناه وقعدنا معاه، نعمل إيه؟\nيبقى نسكت خاااالص، ومنتكلمش\nلأن لو اتكلمنا بعاطفة واحنا مش عارفين حاجة وفاهمين غلط واتهمنا شخص بالنفاق وهو مش منافق، هتبقى مصيبة على دماغنا يوم القيامة\nرسول الله ﷺ بيقول: \n\"سِباب المسلم فسوق\"\nيعني لو أنا شتمت واحدة مسلمة بغير حق أبقى عند ربنا فاسقة والعياذ بالله،\nوالفسق أشد من المعصية فهو الخروج من طاعة ربنا بعمل كبيرة من الكبائر\nمعلش يعني وعلى إيه أعرّض نفسي لغضب ربنا وأعرّض حسناتي إللي أنا تعبت وشقيت عشان أجمعها إنها تتاخد مني يوم القيامة؟\nعشان أقول على حد إنه منافق وأنا أصلا معنديش الدليل الواضح البيّن إنه منافق ومش هستفيد حاجة لما أقول إنه منافق\nيبقى خُلاصة الكلام إننا لو فينا صفة من صفات النفاق العملي نتخلص منها،\nونمسك لساننا ومنقولش ومنتهمش حد بالنفاق إلا لو معانا الدليل الواضح على كده\nغير كده معلش متشكرين أوي، احنا عايزين نحافظ على حسناتنا\nاحنا كده فهمنا إيه هي طائفة المنافقين دي، عشان لما نشوف لهم مواقف ونشوف رد فعل رسول الله ﷺ نكون فاهمين ليه رسول الله ﷺ اتعامل معاهم كده\nانتهى شهر رمضان من السنة الثانية من الهجرة وصلى رسول الله ﷺ أول صلاة عيد بالمسلمين،\nوصلاة العيد بتكون ركعتين، الركعة الأولى فيها سبع تكبيرات قبل قراءة الفاتحة، والركعة الثانية خمس تكبيرات قبل قراءة الفاتحة، وبعد صلاة العيد الإمام بيخطب خطبتين،\nفخرج رسول الله ﷺ مع المسلمين وصلى العيد وخطب خطبة العيد،\nفي قصة حصلت في شهر رمضان وبيرويها الناس وبينشروها وبياخدوها حجة عشان يطعنوا في رسول الله ﷺ \nالقصة إن واحدة اسمها عصماء بنت مروان، كانت بتهجو رسول الله ﷺ ، يعني كانت بتشتمه بالشعر، وكانت بتؤذي المسلمين،\nفرسول الله ﷺ قال لأصحابه من يكفيني هذه المرأة؟\nفقام رجل من قومها وقال أنا يا رسول الله،\nطريقة قتلها بقى فيها روايتين، والروايتين غلط ومن الأحاديث الموضوعة، عشان لو سمعتم حد بيقول الأحاديث دي تقولوا ده كذب عن رسول الله ﷺ \nالرواية الأولى : \nإنها كانت بتبيع تمر، فذهب لها الرجل وسألها عن التمر فمعجبهوش إللي كانت عارضاه للبيع، فقالت له عندي أحسن منه فدخلت في بيتها عشان توريه فدخل معاها وقعد يبص يمين وشمال يدور على حاجة يضربها بها، \nفملقاش غير خُوان يعني زي ما بنقول بالبلدي طبليّة أو ترابيزة،\nفأخذها وقعد يضربها على رأسها لحد ما ماتت،\nوالرواية الثانية بقى بتقول:\nإن الرجل إللي من قومها ده تسلل ودخل بيتها في نص الليل وكانت نايمة وحولها عيالها وكان في رضيع بترضعه،\nفراح واخد الرضيع وباعده عنها وراح ماسك السيف وحطه في صدرها وطلعه من ظهرها وقتلها\nيعني بالعقل رسول الله ﷺ عمره ما يأمر أبدا بقتل امرأة بالمنظر ده،\nأنا لقيت القصة دي في كتاب من الكتب، قلبي وجعني وقلت أكيد القصة دي مش صحيحة وفعلا لما دورت طلعت من الأحاديث الموضوعة\nده غير إنها بتخالف وصايا رسول الله ﷺ في عدم قتل النساء والأطفال، وبتخالف مواقفه في الأحاديث الصحيحة في التعامل مع النساء حتى لو من اليهود زي ما هنشوف إن شاء الله\nوبما إننا جبنا سيرة اليهود يبقى لازم نعرف رد فعلهم كان إيه بعد انتصار المسلمين في غزوة بدر\nبعد غزوة بدر وانتصار رسول الله ﷺ فيها، جمع يهود بني قينقاع إللي كانوا عايشين في المدينة وكانوا قريبين من المسلمين،\nوكان عندهم السوق بتاعهم إللي كان الناس معتمدين عليه في البيع والشراء واتكلمنا عنه قبل كده،\nجمعهم رسول الله ﷺ وقعد يدعوهم للإسلام، \nو قال لهم أسلموا قبل ما يحصل معاكم زي ما حصل مع قريش، \nيعني قريش حاربت دين ربنا فدي كانت نهايتها، فبلاش تعملوا زيهم عشان نهايتكم متكونش زيهم،\nمن باب الاعتبار يعني مش باب إنه بيغصبهم على الدخول في الإسلام\nفهو بيحذرهم لأن طبيعتهم إنهم يخالفوا الحق ويعتدوا على الأنبياء ويسيئوا الأدب معاهم ومع رب العزة،\nولهم كوارث مع رسول الله ﷺ أولها إنهم بعد ما كانوا بيتوعدوا الأوس والخزرج بإنهم هيقتلوهم مع النبي إللي هيظهر، كانوا هم أول المكذبين \nحتى واحد من الصحابة اسمه معاذ بن جبل كان بيقول لهم \nقال لهم: \nيا معشر يهود! اتقوا الله وأسلموا، ده انتم كنتم بتهددونا بمحمد ﷺ وبتقولوا إنكم هتتبعوه وتقتلونا، فإيه إللي غيركم\n فقال رجل من أشراف بني النّضير اسمه سَلام بن مُشْكم :\nماجاش بحاجة من إللي احنا عارفينها وكنا بنقول لكم عليها\nفأنزل الله عز وجل : \n\"وَلَمَّا جَاءَهُمْ كِتَابٌ مِنْ عِنْدِ اللَّهِ مُصَدِّقٌ لِمَا مَعَهُمْ وَكَانُوا مِنْ قَبْلُ يَسْتَفْتِحُونَ عَلَى الَّذِينَ كَفَرُوا فَلَمَّا جَاءَهُمْ مَا عَرَفُوا كَفَرُوا بِهِ فَلَعْنَةُ اللَّهِ عَلَى الْكَافِرِينَ\"\nومش بس كده ده كانوا بيتهموا ربنا بالفقر \nربنا لما أنزل آية: \"مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ لَهُ وَلَهُ أَجْرٌ كَرِيمٌ \"\nولما سمعها اليهود قالوا: افتقر رب محمد\nوقابل أبو بكر الصديق واحد من اليهود اسمه فِنْحاص وكان قاعد وسط مجموعة من اليهود بيشرح لهم التورارة وكان من علمائهم،\nفقال له أبو بكر :\nيا فنْحاص ! اتق الله وأسلم، فوالله إنك لتعلم أن محمداً رسول الله، وإنت عارف إنه جاء بالحق وإنه مكتوب عندكم أوصافه في التوراة\nفقال فنحاص لأبي بكر : \nوالله يا أبا بكر ! ما بنا إلى الله من فقر، وإنه إلينا لفقير!\n يعني احنا مش محتاجين ربنا ده هو محتاجنا،\nوإنا عنه لأغنياء، وما هو عنا بغني\nأبو بكر الصديق مقدرش يستحمل كلام فنحاص راح ماسكه ونازل فيه ضرب\nذهب فنحاص إلى رسول الله ﷺ يحكي له الموقف، وكان تصرف أبي بكر على غير ما اتفق عليه المسلمون، \nلأن كان في بين المسلمين واليهود معاهدة، فالمسلمين مأمورين بالعفو والصفح وعدم الإيذاء،\nفجاء فنحاص وقعد يشتكي لرسول الله ﷺ وقال له:\n شوف صاحبك عمل في إيه \n فسأل رسول الله ﷺ أبا بكر:\nإيه إللي خلاك تعمل فيه كده يا أبا بكر؟\n فقال أبو بكر : يا رسول الله! \nعدو الله ده قال قولاً عظيماً\nبيدعي إن الله فقير وأنهم أغنياء، فلما قال ذلك غضبت لله مما قال، وضربت وجهه \nفأنكر فنحاص وقال: ما قلتش الكلام ده\nفأنزل الله عز وجل:\n\"لَّقَدْ سَمِعَ اللَّهُ قَوْلَ الَّذِينَ قَالُوا إِنَّ اللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَاءُ ۘ سَنَكْتُبُ مَا قَالُوا وَقَتْلَهُمُ الْأَنبِيَاءَ بِغَيْرِ حَقٍّ وَنَقُولُ ذُوقُوا عَذَابَ الْحَرِيقِ\"\nفنزل القرآن موافقا لموقف أبي بكر الصديق رضي الله عنه، \nلما رسول الله ﷺ كلم اليهود ووعظهم عشان يأخذوا العبرة من إللي حصل لقريش في موقعة بدر ، ردوا عليه وقالوا :\nيا محمد!\n متتغرش بنفسك إنك عرفت تقتل كم نفر من قريش كانوا جهلة وميعرفوش إزاي يحاربوا ولا يقاتلوا \n إنت لو قاتلتنا هتعرف إننا احنا أهل القتال وإنك مش هتقابل زينا \nفرينا انزل فيهم:\n\"قَدْ كَانَ لَكُمْ آيَةٌ فِي فِئَتَيْنِ الْتَقَتَا ۖ فِئَةٌ تُقَاتِلُ فِي سَبِيلِ اللَّهِ وَأُخْرَىٰ كَافِرَةٌ يَرَوْنَهُم مِّثْلَيْهِمْ رَأْيَ الْعَيْنِ ۚ وَاللَّهُ يُؤَيِّدُ بِنَصْرِهِ مَن يَشَاءُ ۗ إِنَّ فِي ذَٰلِكَ لَعِبْرَةً لِّأُولِي الْأَبْصَارِ\"\n فكده اليهود بيهددوا رسول الله ﷺ والمسلمين بصورة واضحة بإنهم هيقاتلوه، على الرغم من المعاهدة إللي بينهم، \nفبدأ يكون في قلق في المدينة\nواحدة من المسلمات رايحة تشتري من سوق بني قينقاع، وهي بتشتري اليهود قعدوا يقنعوها عشان تكشف وجهها ولكنها رفضت،\nفراح واحد من اليهود رابط ذيل عبائتها في رأسها من غير ماتاخد بالها،\nفلما قامت انكشفت عورتها، وراحت مصوّتة\nسمعها واحد من المسلمين جه شاف المنظر راح جاي وقتل اليهودي إللي عمل كده،\nراح اليهود مجتمعين عليه قاتلينه، وكده الدنيا هتولع في المدينة\n☆وقبل ما تسألوني هي ليه كانت مغطية وجهها ولسه آية الحجاب منزلتش، هقول لكم معرفش\nأنا دورت فيها وملقتش إجابة، فممكن والله أعلم إنها كانت جاية تشتري من السوق ومش عايزة حد يعرفها فكانت مغطية وجهها\n \nلكن الأكيد إن آية فرض الحجاب مكنتش لسه نزلت\nوصل الخبر لرسول الله ﷺ، إن اليهود قتلوا رجل مسلم،\nودي مش أول مرة يُقتل فيها واحد مسلم في غير حرب،\nقُتل قبل كده ياسر وزوجته سمية،\nورسول الله ﷺ ساعتها معملش حاجة، فهل يا ترى موقف رسول الله ﷺ من مقتل المسلم ده، هيكون زي موقفه من مقتل ياسر وسمية؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}]);
